TUTORIALS.append({'title': 'VIN-3. urls.py', 'category': 'programming', 'order': 3, 'summary': 'The pages: the analysis, «Пересчитать», Excel, the business plan.', 'content': '<p>Step 3 of 11. Save as <code>vintage/urls.py</code>.</p>\n<h3>urls.py</h3>\n<pre><code class="language-python">from django.urls import path\nfrom . import views\n\nurlpatterns = [\n    path("", views.home, name="vintage"),\n    path("rebuild/", views.rebuild, name="vintage-rebuild"),\n    path("excel/", views.excel, name="vintage-excel"),\n    path("plan/", views.plan, name="vintage-plan"),\n]\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-4. process.py', 'category': 'programming', 'order': 4, 'summary': 'Everything: settings at the top (your column names, NPL ≥ 3, 90+), the build (polars), the triangles, the projection, the insights, the plan, Excel.', 'content': '<p>Step 4 of 11. Save as <code>vintage/process.py</code>.</p>\n<h3>process.py</h3>\n<pre><code class="language-python">"""\nVintage analysis of the loan portfolio.\n\nTHE IDEA\nLoans are grouped by the month they were issued (the «поколение», vintage). Each group is\nfollowed month by month — MOB, «месяц жизни» = months since issue — and we ask: what share\nof this group has EVER been bad by MOB k? Ever, not "this month": a loan that went 90+ and\nwas then written off or cured must stay counted, or old vintages look cleaner than they were.\n\nTwo analyses, the same machinery, a different "bad":\n    просрочка  — maks_dni ≥ 30 / 60 / 90   (90+ is the main one)\n    NPL        — npl_category ≥ 3\n\nEach is measured two ways:\n    по количеству — bad loans / loans issued in that month\n    по сумме      — the balance the loan had when it first went bad / the amount ISSUED in\n                    that vintage (given_amount; the first month\'s balance if it is missing).\n                    Dividing by what was issued matters: today\'s balance shrinks with\n                    repayments, and the rate would grow by itself.\n\nEverything is built three times — all passports together and each passport (pervichka,\nvtorichka) on its own — and the page switches with ?seg=.\n\nHOW IT RUNS\n    python manage.py build_vintage      reads datasets/vintage/input/*.parquet (tens of\n                                        millions of rows: polars, in its own process — never\n                                        inside gunicorn) and saves the small results to\n                                        datasets/vintage/result/\n    the page                            reads only those small results, so it is instant.\n\nTHE SECTIONS OF THIS FILE\n    1. Settings                 — everything you may want to change is here\n    2. Building (the command)   — input → loan-months → triangles, transitions, today\'s book\n    3. Reading the results\n    4. The projection           — finishing the young vintages (the chain-ladder idea)\n    5. Insights                 — the sentences at the top of the page\n    6. The plan                 — expected new 90+ / NPL for the next months\n    7. Page helpers             — colours, the curves picture, number formats\n    8. Excel\n"""\nimport datetime as dt\nimport io\nimport json\nimport os\nimport time\nfrom pathlib import Path\n\nimport numpy as np\nimport polars as pl\nfrom django.conf import settings\n\n# ═══════════════════════════════════ 1. SETTINGS ═══════════════════════════════════════\n\nBASE = Path(settings.BASE_DIR) / "datasets" / "vintage"\nINPUT_DIR = BASE / "input"            # put your parquet file(s) here — all *.parquet are read\nRESULT_DIR = BASE / "result"\nSTATUS_FILE = BASE / "status.json"\nLOG_FILE = BASE / "build.log"\n\n# our name → the column name in YOUR parquet. Change the right-hand side if yours differ.\nCOLUMNS = {\n    "date": "report_date",              # the 1st of the month\n    "anketa": "anketa",                 # the loan id (repeats every month)\n    "issue_date": "valuedate",          # when the loan was issued\n    "maks_dni": "maks_dni",             # overdue days in the period\n    "npl_category": "npl_category",     # 1…5 (0 is read as 1)\n    "portfel_amount": "brutto_95_summa",# the balance in the period\n    "given_amount": "given_amount",     # the amount issued (the «по сумме» denominator)\n    "passport": "passport",             # the product: every analysis is built for all + each passport\n}\n# How the passport values are shown. A value not listed here is shown as it is.\nPASSPORTS = {"pervichka": "Первичка", "vtorichka": "Вторичка"}\nALL = "all"                            # the «все паспорта» key in the address (?seg=all)\n# 2024-02-01 in the file means the portfolio at the end of JANUARY. True = shift back a month.\nDATE_IS_NEXT_MONTH = True\n\nNPL_FROM = 3                           # NPL = category ≥ 3\nKINDS = {\n    "dpd30": {"label": "Просрочка 30+", "group": "dpd", "rule": ("dpd", 30)},\n    "dpd60": {"label": "Просрочка 60+", "group": "dpd", "rule": ("dpd", 60)},\n    "dpd90": {"label": "Просрочка 90+", "group": "dpd", "rule": ("dpd", 90)},\n    "npl":   {"label": f"NPL (категория ≥ {NPL_FROM})", "group": "npl", "rule": ("cat", NPL_FROM)},\n}\nMAIN = {"dpd": "dpd90", "npl": "npl"}  # what the plan and the early signal predict\nMEASURES = {"amount": "по сумме", "count": "по количеству"}\n\n# overdue buckets for the transitions table: (from days, name)\nDPD_BUCKETS = [(90, "90+"), (60, "60–89"), (30, "30–59"), (1, "1–29"), (0, "0")]\nNPL_STATES = ["1", "2", "3", "4", "5"]\nGONE = "вышел"                         # not in the portfolio next month: repaid, written off, sold\n\nRECENT_VINTAGES = 12     # the projection learns each month\'s step from the 12 newest vintages that reached it\nMIGRATION_MONTHS = 12    # the transitions table uses the last 12 months\nPLAN_MONTHS = 12\nEARLY_MOB = 3            # the early signal: 30+ at month 3 …\nLATE_MOB = 12            # … predicts 90+ / NPL at month 12\nMOB_SHOWN = list(range(0, 25)) + [30, 36, 42, 48, 54, 60, 66, 72, 78]   # triangle columns\n\nAMOUNT_DIVISOR = 1_000_000\nAMOUNT_UNIT = "млн"\n\n# ═══════════════════════════ 2. BUILDING (the command) ══════════════════════════════════\n\n\ndef input_files():\n    return sorted(INPUT_DIR.glob("*.parquet"))\n\n\ndef add_months(day, n):\n    m = day.year * 12 + day.month - 1 + n\n    return dt.date(m // 12, m % 12 + 1, 1)\n\n\ndef months_between(a, b):\n    return (b.year - a.year) * 12 + b.month - a.month\n\n\ndef mob_expr(month, start):\n    return ((pl.col(month).dt.year().cast(pl.Int32) - pl.col(start).dt.year().cast(pl.Int32)) * 12\n            + pl.col(month).dt.month().cast(pl.Int32) - pl.col(start).dt.month().cast(pl.Int32))\n\n\ndef dpd_bucket(col):\n    expr = pl.when(pl.col(col) &gt;= DPD_BUCKETS[0][0]).then(pl.lit(DPD_BUCKETS[0][1]))\n    for days, name in DPD_BUCKETS[1:]:\n        expr = expr.when(pl.col(col) &gt;= days).then(pl.lit(name))\n    return expr.otherwise(pl.lit("0"))\n\n\ndef bad_expr(kind):\n    col, edge = KINDS[kind]["rule"]\n    return pl.col(col) &gt;= edge\n\n\ndef read_loan_months(files, log=print):\n    """Every file → one row per loan per month: month, anketa, issue, dpd, cat, amount, given, passport."""\n    c = COLUMNS\n    month = pl.col("date").cast(pl.Date)\n    if DATE_IS_NEXT_MONTH:\n        month = month.dt.offset_by("-1mo")\n    lf = (pl.scan_parquet([str(f) for f in files])\n          .select(pl.col(c["date"]).alias("date"), pl.col(c["anketa"]).alias("anketa"),\n                  pl.col(c["issue_date"]).cast(pl.Date).alias("issue"),\n                  pl.col(c["maks_dni"]).cast(pl.Float64).fill_null(0).alias("dpd"),\n                  pl.col(c["npl_category"]).cast(pl.Float64).fill_null(1).alias("cat"),\n                  pl.col(c["portfel_amount"]).cast(pl.Float64).fill_null(0).alias("amount"),\n                  pl.col(c["given_amount"]).cast(pl.Float64).alias("given"),\n                  pl.col(c["passport"]).cast(pl.Utf8).str.strip_chars().alias("passport"))\n          .with_columns(month.dt.truncate("1mo").alias("month"),\n                        pl.col("issue").dt.truncate("1mo"),\n                        pl.col("cat").clip(1, 5).cast(pl.Int8)))\n    rows = lf.select(pl.len()).collect().item()\n    log(f"rows in the files: {rows:,}")\n    # one row per loan and month: several accounts of one loan are added up (the balance);\n    # the issued amount is the same on every row of a loan, so it is not added up\n    lm = (lf.group_by("anketa", "month")\n            .agg(pl.col("issue").min(), pl.col("dpd").max(), pl.col("cat").max(), pl.col("amount").sum(),\n                 pl.col("given").max(), pl.col("passport").drop_nulls().first())\n            .collect()\n            .sort("anketa", "month"))\n    log(f"loan-months: {lm.height:,}")\n    return lm, rows\n\n\ndef month_index(col):\n    """A month as one number (year × 12 + month) — easy to compare and to add MOBs to."""\n    return pl.col(col).dt.year().cast(pl.Int32) * 12 + pl.col(col).dt.month().cast(pl.Int32) - 1\n\n\ndef transitions(lm, last_month, data_months):\n    """Where each loan was the next month, for the last MIGRATION_MONTHS months: count,\n    the balance at the start (for the shares) and the balance a month later (for the forecast).\n    Only months whose NEXT month is in the data: across a quarterly gap every loan would look «вышел»."""\n    first = add_months(last_month, -MIGRATION_MONTHS)\n    has_next = [m for m in data_months if add_months(m, 1) in set(data_months)]\n    nxt = lm.with_columns(pl.col("month").shift(-1).over("anketa").alias("next_month"),\n                          pl.col("dpd").shift(-1).over("anketa").alias("next_dpd"),\n                          pl.col("cat").shift(-1).over("anketa").alias("next_cat"),\n                          pl.col("amount").shift(-1).over("anketa").alias("next_amount"))\n    pairs = nxt.filter((pl.col("month") &gt;= first) &amp; (pl.col("month") &lt; last_month) &amp; pl.col("month").is_in(has_next))\n    stayed = pl.col("next_month") == pl.col("month").dt.offset_by("1mo")\n    out = []\n    for group, frm, to in [\n        ("dpd", dpd_bucket("dpd"), dpd_bucket("next_dpd")),\n        ("npl", pl.col("cat").cast(pl.Utf8), pl.col("next_cat").cast(pl.Utf8)),\n    ]:\n        t = (pairs.with_columns(frm.alias("from"),\n                                pl.when(stayed).then(to).otherwise(pl.lit(GONE)).alias("to"),\n                                pl.when(stayed).then(pl.col("next_amount")).otherwise(0.0).alias("next_amount"))\n             .group_by("from", "to")\n             .agg(pl.len().alias("count"), pl.col("amount").sum(), pl.col("next_amount").sum())\n             .with_columns(pl.lit(group).alias("group")))\n        out.append(t)\n    return pl.concat(out)\n\n\ndef book_today(lm, last_month):\n    """The portfolio in the last month by state — where the transitions forecast starts."""\n    now = lm.filter(pl.col("month") == last_month)\n    return pl.concat([\n        now.with_columns(dpd_bucket("dpd").alias("state")).group_by("state")\n           .agg(pl.len().alias("count"), pl.col("amount").sum()).with_columns(pl.lit("dpd").alias("group")),\n        now.with_columns(pl.col("cat").cast(pl.Utf8).alias("state")).group_by("state")\n           .agg(pl.len().alias("count"), pl.col("amount").sum()).with_columns(pl.lit("npl").alias("group")),\n    ])\n\n\ndef triangles(lm, first_month, last_month, data_months):\n    """The vintage triangles: for every vintage and MOB, how many loans (and how much balance)\n    have EVER been bad by that month. Only cells whose calendar month is in the data: in the\n    quarterly years (2020–2021) a vintage has a value every third month, the cells between\n    are left out (empty in the table), never guessed."""\n    v = lm.filter(pl.col("issue") &gt;= first_month).with_columns(mob_expr("month", "issue").alias("mob"))\n    v = v.filter(pl.col("mob") &gt;= 0)\n    loans = v.group_by("anketa").agg(\n        pl.col("issue").first().alias("vintage"),\n        # the base of «по сумме»: the issued amount; the first month\'s balance if it is missing\n        pl.when(pl.col("given").first() &gt; 0).then(pl.col("given").first())\n          .otherwise(pl.col("amount").first()).alias("start_amount"),   # rows are sorted by month\n        *[pl.col("mob").filter(bad_expr(k)).min().alias(f"{k}_mob") for k in KINDS],\n        *[pl.col("amount").filter(bad_expr(k)).first().alias(f"{k}_amount") for k in KINDS],\n    )\n    vint = (loans.group_by("vintage").agg(pl.len().alias("loans"), pl.col("start_amount").sum().alias("base"))\n            .with_columns(((last_month.year - pl.col("vintage").dt.year().cast(pl.Int32)) * 12\n                           + last_month.month - pl.col("vintage").dt.month().cast(pl.Int32)).alias("age")))\n    k_max = months_between(first_month, last_month)\n    grid = (vint.join(pl.DataFrame({"mob": list(range(k_max + 1))}, schema={"mob": pl.Int32}), how="cross")\n            .filter(pl.col("mob") &lt;= pl.col("age"))\n            .filter((month_index("vintage") + pl.col("mob")).is_in([m.year * 12 + m.month - 1 for m in data_months])))\n    out = []\n    for k in KINDS:\n        ev = (loans.filter(pl.col(f"{k}_mob").is_not_null())\n              .group_by("vintage", pl.col(f"{k}_mob").cast(pl.Int32).alias("mob"))\n              .agg(pl.len().alias("new_count"), pl.col(f"{k}_amount").sum().alias("new_amount")))\n        t = (grid.join(ev, on=["vintage", "mob"], how="left")\n             .with_columns(pl.col("new_count").fill_null(0), pl.col("new_amount").fill_null(0.0))\n             .sort("vintage", "mob")\n             .with_columns(pl.col("new_count").cum_sum().over("vintage").alias("bad_count"),\n                           pl.col("new_amount").cum_sum().over("vintage").alias("bad_amount"))\n             .with_columns(pl.lit(k).alias("kind")))\n        out.append(t)\n    return pl.concat(out).select("kind", "vintage", "mob", "loans", "base", "bad_count", "bad_amount")\n\n\ndef build(log=print):\n    """The whole build: input files → datasets/vintage/result/. Returns the meta dict."""\n    started = time.time()\n    files = input_files()\n    if not files:\n        raise FileNotFoundError(f"нет файлов *.parquet в {INPUT_DIR}")\n    lm, rows = read_loan_months(files, log)\n    checks = {"Строк в файлах": rows, "Строк объединено (один кредит дважды в месяц)": rows - lm.height}\n\n    no_issue = lm.filter(pl.col("issue").is_null())["anketa"].n_unique()\n    lm = lm.with_columns(pl.col("issue").min().over("anketa"))       # one issue month per loan\n    first_month, last_month = lm["month"].min(), lm["month"].max()\n    data_months = sorted(lm["month"].unique().to_list())\n    missing = [add_months(first_month, i) for i in range(months_between(first_month, last_month) + 1)\n               if add_months(first_month, i) not in set(data_months)]\n    checks["Кредитов без даты выдачи (не попали в поколения)"] = no_issue\n    before = lm.filter(pl.col("issue") &lt; first_month)["anketa"].n_unique()\n    checks[f"Кредитов, выданных до {first_month:%m.%Y} (нет начала истории — не в поколениях, но в переходах)"] = before\n    wrong = lm.filter(pl.col("month") &lt; pl.col("issue"))["anketa"].n_unique()\n    checks["Кредитов с отчётом раньше даты выдачи (эти месяцы пропущены)"] = wrong\n    checks["Месяцев без данных (квартальные годы — пустые клетки в треугольнике)"] = len(missing)\n\n    # one passport per loan: the latest one it had (and how many loans changed it)\n    pas = (lm.filter(pl.col("passport").is_not_null()).group_by("anketa")\n             .agg(pl.col("passport").last(), pl.col("passport").n_unique().alias("passports")))\n    checks["Кредитов, сменивших паспорт (взят последний)"] = pas.filter(pl.col("passports") &gt; 1).height\n    lm = lm.drop("passport").join(pas.select("anketa", "passport"), on="anketa", how="left") \\\n           .with_columns(pl.col("passport").fill_null("не указан")).sort("anketa", "month")\n    checks["Кредитов без суммы выдачи (база «по сумме» = остаток 1-го месяца)"] = \\\n        lm.filter(~(pl.col("given") &gt; 0))["anketa"].n_unique()\n    counts = lm.group_by("passport").agg(pl.col("anketa").n_unique().alias("loans")).sort("loans", descending=True)\n    segments = [{"key": ALL, "label": "Все паспорта", "loans": int(lm["anketa"].n_unique())}] + \\\n               [{"key": r["passport"], "label": PASSPORTS.get(r["passport"], r["passport"]), "loans": int(r["loans"])}\n                for r in counts.iter_rows(named=True)]\n\n    tri, tr, bk = [], [], []\n    for seg in segments:\n        part = lm if seg["key"] == ALL else lm.filter(pl.col("passport") == seg["key"])\n        log(f"{seg[\'label\']}: {seg[\'loans\']:,} loans — transitions, today\'s book, triangles …")\n        tag = pl.lit(seg["key"]).alias("seg")\n        tr.append(transitions(part, last_month, data_months).with_columns(tag))\n        bk.append(book_today(part, last_month).with_columns(tag))\n        tri.append(triangles(part, first_month, last_month, data_months).with_columns(tag))\n    tri, tr, bk = pl.concat(tri), pl.concat(tr), pl.concat(bk)\n\n    RESULT_DIR.mkdir(parents=True, exist_ok=True)\n    for name, table in [("triangle", tri), ("transitions", tr), ("book", bk)]:\n        tmp = RESULT_DIR / f"{name}.parquet.tmp"\n        table.write_parquet(tmp)\n        os.replace(tmp, RESULT_DIR / f"{name}.parquet")\n    meta = {\n        "first_month": first_month.isoformat(), "last_month": last_month.isoformat(),\n        "built_at": dt.datetime.now().isoformat(timespec="seconds"),\n        "seconds": round(time.time() - started, 1),\n        "loans": int(lm["anketa"].n_unique()),\n        "segments": segments,\n        "files": [f.name for f in files], "checks": checks,\n        "missing_from": missing[0].isoformat() if missing else None,\n        "missing_to": missing[-1].isoformat() if missing else None,\n    }\n    (RESULT_DIR / "meta.json").write_text(json.dumps(meta, ensure_ascii=False, indent=1))\n    log(f"done in {meta[\'seconds\']} s")\n    return meta\n\n\n# ═══════════════════════════════ 3. READING THE RESULTS ════════════════════════════════\n\nCACHE = {"stamp": None, "data": None}\n\n\ndef results():\n    """The saved results (None if never built). Read once, re-read when the build changes them."""\n    meta_file = RESULT_DIR / "meta.json"\n    if not meta_file.exists():\n        return None\n    stamp = meta_file.stat().st_mtime\n    if CACHE["stamp"] != stamp:\n        meta = json.loads(meta_file.read_text())\n        meta["first_month"] = dt.date.fromisoformat(meta["first_month"])\n        meta["last_month"] = dt.date.fromisoformat(meta["last_month"])\n        for key in ("missing_from", "missing_to"):\n            meta[key] = dt.date.fromisoformat(meta[key]) if meta.get(key) else None\n        CACHE["data"] = {\n            "meta": meta,\n            "triangle": pl.read_parquet(RESULT_DIR / "triangle.parquet"),\n            "transitions": pl.read_parquet(RESULT_DIR / "transitions.parquet"),\n            "book": pl.read_parquet(RESULT_DIR / "book.parquet"),\n        }\n        CACHE["stamp"] = stamp\n    return CACHE["data"]\n\n\ndef matrix(res, kind, measure, seg=ALL):\n    """The triangle as numbers: vintages (list of dates), R[vintage, mob] (NaN = not reached\n    yet), weight per vintage (issued amount or number of loans). seg = a passport or ALL."""\n    t = res["triangle"].filter((pl.col("kind") == kind) &amp; (pl.col("seg") == seg)).sort("vintage", "mob")\n    vint = t.group_by("vintage").agg(pl.col("loans").first(), pl.col("base").first()).sort("vintage")\n    vintages = vint["vintage"].to_list()\n    k = months_between(res["meta"]["first_month"], res["meta"]["last_month"]) + 1\n    R = np.full((len(vintages), k), np.nan)\n    pos = {v: i for i, v in enumerate(vintages)}\n    vi = np.array([pos[v] for v in t["vintage"].to_list()], dtype=int)\n    mi = t["mob"].to_numpy()\n    if measure == "amount":\n        base = t["base"].to_numpy()\n        R[vi, mi] = np.divide(t["bad_amount"].to_numpy(), base, out=np.zeros(len(base)), where=base &gt; 0)\n        weight = vint["base"].to_numpy().astype(float)\n    else:\n        R[vi, mi] = t["bad_count"].to_numpy() / t["loans"].to_numpy()\n        weight = vint["loans"].to_numpy().astype(float)\n    return vintages, R, weight\n\n\n# ═══════════════════════════════════ 4. THE PROJECTION ═════════════════════════════════\n#\n# A young vintage has only a few months. To finish its row we borrow the STEPS of the older\n# rows: on average, how much does the rate grow from month k-1 to month k? (taken from the\n# RECENT_VINTAGES newest vintages that have reached month k, weighted by their size). The young\n# row then continues from its own last real value by those average steps — so a bad vintage\n# stays bad, it just ages like the others. This is the chain-ladder idea in its additive form,\n# which does not break when early months are 0.\n\ndef average_steps(R, weight):\n    k = R.shape[1]\n    steps = np.zeros(k)\n    reached = np.zeros(k, dtype=int)\n    inc = np.diff(R, axis=1, prepend=0.0)          # inc[:, 0] = R[:, 0]\n    for m in range(k):\n        rows = np.where(~np.isnan(inc[:, m]))[0][-RECENT_VINTAGES:]\n        reached[m] = len(rows)\n        if len(rows) and weight[rows].sum() &gt; 0:\n            steps[m] = np.average(inc[rows, m], weights=weight[rows])\n    return steps, reached\n\n\ndef projected(R, steps, extra=0):\n    """R continued AFTER each row\'s last real value by the average steps (and `extra` months\n    beyond the longest history, where the curve stays flat). Empty cells BEFORE the last real\n    value (the quarterly years) stay empty: they are the past, not something to forecast.\n    Returns (P, is_projected)."""\n    v, k = R.shape\n    steps = np.concatenate([steps, np.zeros(extra)])\n    P = np.concatenate([R, np.full((v, extra), np.nan)], axis=1)\n    proj = np.zeros(P.shape, dtype=bool)\n    for i in range(v):\n        real = np.where(~np.isnan(R[i]))[0]\n        for m in range(real[-1] + 1 if len(real) else 0, k + extra):\n            P[i, m] = min(1.0, (P[i, m - 1] if m else 0.0) + steps[m])\n            proj[i, m] = True\n    return P, proj\n\n\ndef typical_curve(steps):\n    """The expected curve of a NEW vintage: month 0, 1, 2 … (cumulative average steps)."""\n    return np.minimum(1.0, np.cumsum(steps))\n\n\n# ═══════════════════════════════════ 5. INSIGHTS ═══════════════════════════════════════\n\ndef reference_mob(R):\n    """The month to compare vintages at: 12 if at least 6 vintages reached it, else 6, else 3."""\n    reached = (~np.isnan(R)).sum(axis=0)\n    for m in (12, 6, 3, 1):\n        if m &lt; R.shape[1] and reached[m] &gt;= 6:\n            return m\n    return 0\n\n\ndef pct(x, digits=2):\n    return "—" if x is None or np.isnan(x) else f"{x * 100:.{digits}f}%".replace(".", ",")\n\n\ndef num(x, digits=2):\n    return f"{x:.{digits}f}".replace(".", ",")\n\n\ndef month_name(day):\n    return f"{day:%m.%Y}"\n\n\nRU_MONTHS = ["январь", "февраль", "март", "апрель", "май", "июнь", "июль", "август",\n             "сентябрь", "октябрь", "ноябрь", "декабрь"]\n\n\ndef insights(vintages, R, weight, steps, kind, measure):\n    """A few sentences a manager can read without the table."""\n    label = KINDS[kind]["label"]\n    out = []\n    ref = reference_mob(R)\n    col = R[:, ref]\n    seen = ~np.isnan(col)\n    if seen.sum() &gt;= 3:\n        avg = np.average(col[seen], weights=weight[seen]) if weight[seen].sum() else col[seen].mean()\n        worst, best = np.nanargmax(np.where(seen, col, -1)), np.nanargmin(np.where(seen, col, 2))\n        out.append(f"На {ref}-м месяце жизни в среднем {pct(avg)} кредитов ({MEASURES[measure]}) уже были в «{label}». "\n                   f"Хуже всех — выданные в {month_name(vintages[worst])}: {pct(col[worst])}, "\n                   f"лучше всех — {month_name(vintages[best])}: {pct(col[best])}.")\n        idx = np.where(seen)[0]\n        if len(idx) &gt;= 12:\n            new, old = idx[-6:], idx[-18:-6]\n            a = np.average(col[new], weights=weight[new]) if weight[new].sum() else col[new].mean()\n            b = np.average(col[old], weights=weight[old]) if weight[old].sum() else col[old].mean()\n            word = "хуже" if a &gt; b else "лучше"\n            out.append(f"Последние 6 поколений, дошедших до {ref}-го месяца ({month_name(vintages[new[0]])}–"\n                       f"{month_name(vintages[new[-1]])}): {pct(a)} против {pct(b)} у 12 предыдущих — "\n                       f"{word} на {num(abs(a - b) * 100)} п.п.")\n    curve = typical_curve(steps)\n    if len(curve) &gt; 24 and curve[24] &gt; 0:\n        out.append(f"Типичное поколение к 6-му месяцу набирает {curve[6] / curve[24] * 100:.0f}% того, что наберёт "\n                   f"к 24-му, к 12-му — {curve[12] / curve[24] * 100:.0f}%. Значит, о новом поколении можно "\n                   f"судить уже через полгода–год.")\n    if len(steps) &gt; 2 and steps[1:].max() &gt; 0:\n        peak = int(np.argmax(steps[1:]) + 1)\n        out.append(f"Больше всего новых случаев появляется на {peak}-м месяце жизни "\n                   f"(+{num(steps[peak] * 100)} п.п. за этот месяц).")\n    season = seasonality(vintages, R, weight, ref)\n    if season:\n        top = max(season, key=lambda s: s["raw"])\n        low = min(season, key=lambda s: s["raw"])\n        out.append(f"По месяцу выдачи: хуже всего — кредиты, выданные в месяц «{top[\'name\']}» ({top[\'value\']} на "\n                   f"{ref}-м месяце), лучше всего — «{low[\'name\']}» ({low[\'value\']}).")\n    return out, ref\n\n\ndef seasonality(vintages, R, weight, ref):\n    """The rate at month `ref` averaged by the calendar month of issue (only if every calendar\n    month has at least 2 vintages)."""\n    col = R[:, ref]\n    rows = []\n    for m in range(1, 13):\n        idx = [i for i, v in enumerate(vintages) if v.month == m and not np.isnan(col[i])]\n        if len(idx) &lt; 2:\n            return []\n        w = weight[idx]\n        raw = float(np.average(col[idx], weights=w)) if w.sum() else float(col[idx].mean())\n        rows.append({"name": RU_MONTHS[m - 1], "raw": raw, "value": pct(raw), "n": len(idx)})\n    top = max(r["raw"] for r in rows) or 1\n    for r in rows:\n        r["bar"] = round(r["raw"] / top * 100)\n    return rows\n\n\ndef early_signal(res, late_kind, seg=ALL):\n    """Does 30+ at month EARLY_MOB predict LATE_MOB? Fitted on the vintages that reached\n    LATE_MOB, then used on the young ones. Returns None when there is too little history."""\n    vintages, X, w = matrix(res, "dpd30", "amount", seg)\n    _, Y, _ = matrix(res, late_kind, "amount", seg)\n    if X.shape[1] &lt;= LATE_MOB:\n        return None\n    x, y = X[:, EARLY_MOB], Y[:, LATE_MOB]\n    fit = ~np.isnan(x) &amp; ~np.isnan(y)\n    if fit.sum() &lt; 8 or np.std(x[fit]) == 0:\n        return None\n    b, a = np.polyfit(x[fit], y[fit], 1)\n    r = float(np.corrcoef(x[fit], y[fit])[0, 1])\n    steps, _ = average_steps(Y, w)\n    P, _ = projected(Y, steps)\n    young = [i for i in range(len(vintages)) if not np.isnan(x[i]) and np.isnan(y[i])]\n    rows = [{"vintage": month_name(vintages[i]), "early": pct(x[i]),\n             "by_signal": pct(max(0.0, a + b * x[i])), "by_curve": pct(P[i, LATE_MOB])} for i in young]\n    strength = "сильная" if abs(r) &gt;= 0.7 else "средняя" if abs(r) &gt;= 0.4 else "слабая"\n    return {"r": num(r), "strength": strength, "n": int(fit.sum()),\n            "formula": f"{KINDS[late_kind][\'label\']} на {LATE_MOB}-м мес. ≈ {num(a * 100)}% + "\n                       f"{num(b)} × (30+ на {EARLY_MOB}-м мес.)",\n            "rows": rows[-12:], "late_label": KINDS[late_kind]["label"]}\n\n\ndef segments(res):\n    """[{\'key\', \'label\', \'loans\'}] — ALL first, then each passport, biggest first."""\n    return res["meta"]["segments"]\n\n\ndef segment_label(res, seg):\n    return next((s["label"] for s in segments(res) if s["key"] == seg), seg)\n\n\ndef loans_in_vintages(res, seg=ALL):\n    t = res["triangle"].filter((pl.col("kind") == "dpd90") &amp; (pl.col("seg") == seg))\n    return int(t.group_by("vintage").agg(pl.col("loans").first())["loans"].sum())\n\n\nCOMPARE_MOBS = (6, 12, 24)\n\n\ndef compare(res, kind, measure):\n    """The passports side by side: each one\'s typical curve (how a vintage issued today is\n    expected to age) and the actual average of its vintages that reached MOB 6 / 12 / 24.\n    Returns None when there is only one passport."""\n    segs = [s for s in segments(res) if s["key"] != ALL]\n    if len(segs) &lt; 2:\n        return None\n    rows, lines = [], []\n    for n, s in enumerate(segments(res)):\n        vintages, R, w = matrix(res, kind, measure, s["key"])\n        if not vintages:\n            continue\n        steps, _ = average_steps(R, w)\n        curve = typical_curve(steps)\n        cells = []\n        for m in COMPARE_MOBS:\n            seen = [i for i in range(len(vintages)) if m &lt; R.shape[1] and not np.isnan(R[i, m])][-RECENT_VINTAGES:]\n            fact = np.average(R[seen, m], weights=w[seen]) if seen and w[seen].sum() else np.nan\n            cells.append({"curve": pct(curve[m]) if m &lt; len(curve) else "—", "fact": pct(fact)})\n        rows.append({"key": s["key"], "label": s["label"], "loans": f"{s[\'loans\']:,}".replace(",", " "),\n                     "cells": cells, "raw12": curve[12] if len(curve) &gt; 12 else np.nan, "all": s["key"] == ALL})\n        lines.append({"name": s["label"], "colour": "#0B0B0C" if s["key"] == ALL else COLOURS[(n + 1) % len(COLOURS)],\n                      "pts": list(enumerate(curve[:37])), "dashed": s["key"] == ALL})\n    sentence = None\n    a, b = [r for r in rows if not r["all"]][:2]\n    if a["raw12"] &gt; 0 and b["raw12"] &gt; 0:\n        worse, better = (a, b) if a["raw12"] &gt; b["raw12"] else (b, a)\n        sentence = (f"«{worse[\'label\']}» хуже: по типичной кривой к 12-му месяцу {pct(worse[\'raw12\'])} против "\n                    f"{pct(better[\'raw12\'])} у «{better[\'label\']}» — в {num(worse[\'raw12\'] / better[\'raw12\'], 1)} раза.")\n    return {"rows": rows, "mobs": COMPARE_MOBS, "chart": chart(lines, 37), "sentence": sentence}\n\n\n# ═══════════════════════════════════ 6. THE PLAN ═══════════════════════════════════════\n#\n# Two parts, both in money (the amount issued in each vintage):\n#   from today\'s book  — each existing vintage continues along its finished row (section 4);\n#                        the growth of its rate in month t × its issued amount = new bad money\n#   from new lending   — each planned month of lending follows the typical curve.\n# The result is a FLOW: how much balance newly reaches 90+ / NPL in each future month.\n\ndef default_lending(res, kind, seg=ALL):\n    """The average monthly issuance of the last 12 months (the plan\'s starting suggestion)."""\n    t = res["triangle"].filter((pl.col("kind") == kind) &amp; (pl.col("seg") == seg))\n    vint = t.group_by("vintage").agg(pl.col("base").first()).sort("vintage")\n    return float(vint["base"].tail(12).mean()) if vint.height else 0.0\n\n\ndef plan(res, kind, lending, growth, seg=ALL, months=PLAN_MONTHS):\n    vintages, R, weight = matrix(res, kind, "amount", seg)\n    steps, _ = average_steps(R, weight)\n    P, _ = projected(R, steps, extra=months + 1)\n    curve = typical_curve(np.concatenate([steps, np.zeros(months + 1)]))\n    last = res["meta"]["last_month"]\n    ages = np.array([months_between(v, last) for v in vintages])\n    rows, total_cum = [], 0.0\n    issued = [lending * (1 + growth) ** s for s in range(months)]\n    for t in range(1, months + 1):\n        book = float(np.sum(weight * (P[np.arange(len(vintages)), ages + t] - P[np.arange(len(vintages)), ages + t - 1])))\n        new = 0.0\n        for s in range(1, t + 1):                         # lending of month s is at month t - s of its life\n            m = t - s\n            new += issued[s - 1] * (curve[m] - (curve[m - 1] if m else 0.0))\n        total_cum += book + new\n        rows.append({"month": add_months(last, t), "book": book, "new": new, "total": book + new,\n                     "cum": total_cum, "lending": issued[t - 1]})\n    return rows\n\n\ndef markov(res, group, lending, growth, seg=ALL, months=PLAN_MONTHS):\n    """The second route: today\'s book by state, moved month by month with the transitions\n    table (balance a month later / balance now), plus the new lending entering the best state.\n    Gives the SHARE of bad balance in the portfolio — a stock, where the plan above is a flow."""\n    states = [n for _, n in reversed(DPD_BUCKETS)] if group == "dpd" else NPL_STATES\n    bad = {"90+"} if group == "dpd" else set(NPL_STATES[NPL_FROM - 1:])\n    tr = res["transitions"].filter((pl.col("group") == group) &amp; (pl.col("seg") == seg))\n    M = np.zeros((len(states), len(states)))\n    for row in tr.iter_rows(named=True):\n        if row["from"] in states and row["to"] in states:\n            M[states.index(row["from"]), states.index(row["to"])] += row["next_amount"]\n    out_of = np.zeros(len(states))\n    for row in tr.iter_rows(named=True):\n        if row["from"] in states:\n            out_of[states.index(row["from"])] += row["amount"]\n    M = np.divide(M, out_of[:, None], out=np.zeros_like(M), where=out_of[:, None] &gt; 0)\n    book = res["book"].filter((pl.col("group") == group) &amp; (pl.col("seg") == seg))\n    s = np.zeros(len(states))\n    for row in book.iter_rows(named=True):\n        if row["state"] in states:\n            s[states.index(row["state"])] = row["amount"]\n    last = res["meta"]["last_month"]\n    bad_idx = [states.index(b) for b in bad]\n    rows = [{"month": last, "share": s[bad_idx].sum() / s.sum() if s.sum() else 0, "total": s.sum(),\n             "bad": s[bad_idx].sum(), "fact": True}]\n    for t in range(1, months + 1):\n        s = s @ M\n        s[0] += lending * (1 + growth) ** (t - 1)\n        rows.append({"month": add_months(last, t), "share": s[bad_idx].sum() / s.sum() if s.sum() else 0,\n                     "total": s.sum(), "bad": s[bad_idx].sum(), "fact": False})\n    return rows\n\n\n# ═══════════════════════════════════ 7. PAGE HELPERS ═══════════════════════════════════\n\ndef money(x):\n    return f"{x / AMOUNT_DIVISOR:,.1f}".replace(",", " ").replace(".", ",")\n\n\ndef heat(x, top):\n    """White → Kapital yellow → red as the rate goes from 0 to `top`."""\n    if x is None or np.isnan(x) or top &lt;= 0:\n        return "#FFFFFF", "#0B0B0C"\n    f = max(0.0, min(1.0, x / top))\n    stops = [(0.0, (255, 255, 255)), (0.5, (242, 194, 48)), (1.0, (179, 52, 31))]\n    for (f0, c0), (f1, c1) in zip(stops, stops[1:]):\n        if f &lt;= f1:\n            g = (f - f0) / (f1 - f0)\n            rgb = [round(a + (b - a) * g) for a, b in zip(c0, c1)]\n            break\n    return "#%02X%02X%02X" % tuple(rgb), ("#FFFFFF" if f &gt; 0.75 else "#0B0B0C")\n\n\ndef triangle_table(vintages, R, P, proj):\n    """Rows for the template: vintage, cells (text, background, colour, projected?)."""\n    mobs = [m for m in MOB_SHOWN if m &lt; R.shape[1]]\n    shown = P[:, mobs]\n    positive = shown[shown &gt; 0]\n    top = float(np.percentile(positive, 95)) if positive.size else 0\n    rows = []\n    for i, v in enumerate(vintages):\n        cells = []\n        for m in mobs:\n            if np.isnan(P[i, m]):                         # a month the data does not have (quarterly years)\n                cells.append({"text": "", "gap": True})\n                continue\n            bg, fg = heat(P[i, m], top)\n            cells.append({"text": f"{P[i, m] * 100:.2f}".replace(".", ","), "bg": bg, "fg": fg, "proj": bool(proj[i, m])})\n        rows.append({"vintage": month_name(v), "year_start": v.month == 1, "cells": cells})\n    return mobs, rows[::-1]                              # newest on top\n\n\nCOLOURS = ["#8A867C", "#2A6F97", "#2E7D4F", "#C9971A", "#7B4FA0", "#B3341F", "#0B0B0C", "#D2691E", "#4F8A8B"]\n\n\ndef curves_svg(vintages, R, weight, steps, last_month):\n    """The picture: one line per issue year (the weighted average of its vintages, real data\n    only) and the dashed typical curve the projection uses.\n    In the quarterly years only a third of a year\'s vintages have a value in any given month,\n    so a month is skipped when none has one, and the line stops when fewer than half the\n    year\'s vintages are old enough."""\n    k = min(R.shape[1], 61)\n    years = sorted({v.year for v in vintages})\n    lines = []\n    for n, y in enumerate(years):\n        idx = [i for i, v in enumerate(vintages) if v.year == y]\n        pts = []\n        for m in range(k):\n            old_enough = [i for i in idx if months_between(vintages[i], last_month) &gt;= m]\n            if len(old_enough) &lt; max(1, len(idx) // 2):\n                break\n            ok = [i for i in old_enough if not np.isnan(R[i, m])]\n            if not ok:\n                continue\n            w = weight[ok]\n            pts.append((m, float(np.average(R[ok, m], weights=w)) if w.sum() else float(R[ok, m].mean())))\n        if pts:\n            lines.append({"name": str(y), "colour": COLOURS[n % len(COLOURS)], "pts": pts})\n    lines.append({"name": "типичная кривая", "colour": "#0B0B0C", "dashed": True,\n                  "pts": list(enumerate(typical_curve(steps)[:k]))})\n    return chart(lines, k)\n\n\ndef chart(lines, k):\n    """Lines [{\'name\', \'colour\', \'pts\': [(mob, rate)], \'dashed\'?}] → everything the template\n    needs to draw a plain SVG (no JavaScript): polylines, the y grid and the x ticks."""\n    top = max([r for line in lines for _, r in line["pts"]] + [1e-9]) * 1.1\n    W, H, L, B = 900, 320, 52, 30\n\n    def xy(m, r):\n        return L + m / max(k - 1, 1) * (W - L - 10), H - B - r / top * (H - B - 10)\n\n    for line in lines:\n        line["points"] = " ".join("%.1f,%.1f" % xy(m, r) for m, r in line["pts"])\n    grid = [{"y": "%.1f" % xy(0, top * g / 4)[1], "label": pct(top * g / 4, 1)} for g in range(5)]\n    ticks = [{"x": "%.1f" % xy(m, 0)[0], "label": m} for m in range(0, k, 6)]\n    return {"lines": lines, "grid": grid, "ticks": ticks,\n            "W": W, "H": H, "L": L, "B": B, "x_end": W - 10, "y_axis": H - B}\n\n\ndef transitions_table(res, group, measure, seg=ALL):\n    """The transitions as shares of each row, plus the key flows in words."""\n    states = [n for _, n in reversed(DPD_BUCKETS)] if group == "dpd" else NPL_STATES\n    cols = states + [GONE]\n    tr = res["transitions"].filter((pl.col("group") == group) &amp; (pl.col("seg") == seg))\n    value = "amount" if measure == "amount" else "count"\n    cell = {(r["from"], r["to"]): r[value] for r in tr.iter_rows(named=True)}\n    rows, share = [], {}\n    for s in states:\n        total = sum(cell.get((s, c), 0) for c in cols)\n        cells = []\n        for c in cols:\n            x = cell.get((s, c), 0) / total if total else np.nan\n            share[(s, c)] = x\n            bg, fg = ("#FFF6D6", "#0B0B0C") if s == c else heat(x, 0.5)\n            cells.append({"text": "—" if np.isnan(x) else f"{x * 100:.1f}".replace(".", ","), "bg": bg, "fg": fg,\n                          "diag": s == c})\n        rows.append({"state": s, "cells": cells,\n                     "total": money(total) if measure == "amount" else f"{int(total):,}".replace(",", " ")})\n\n    def flow(frm, to):\n        num = sum(cell.get((f, t), 0) for f in frm for t in to)\n        den = sum(cell.get((f, c), 0) for f in frm for c in cols)\n        return pct(num / den, 1) if den else "—"\n\n    if group == "dpd":\n        key = [("Из 1–29 вернулись в 0 (вылечились)", flow(["1–29"], ["0"])),\n               ("Из 0 ушли в просрочку", flow(["0"], ["1–29", "30–59", "60–89", "90+"])),\n               ("Из 60–89 перешли в 90+", flow(["60–89"], ["90+"])),\n               ("Из 90+ вернулись в 0", flow(["90+"], ["0"]))]\n    else:\n        good, bad = NPL_STATES[:NPL_FROM - 1], NPL_STATES[NPL_FROM - 1:]\n        key = [(f"Из {NPL_FROM - 1} перешли в NPL (≥ {NPL_FROM})", flow([str(NPL_FROM - 1)], bad)),\n               ("Из 1 сразу в NPL", flow(["1"], bad)),\n               ("Из NPL вернулись в 1–2 (вылечились)", flow(bad, good)),\n               ("NPL вышли из портфеля за месяц", flow(bad, [GONE]))]\n    return {"cols": cols, "rows": rows, "key": key}\n\n\n# ═══════════════════════════════════════ 8. EXCEL ══════════════════════════════════════\n\ndef xlsx(sheets):\n    """[(sheet name, header row, rows)] → .xlsx bytes."""\n    import openpyxl\n    book = openpyxl.Workbook(write_only=True)\n    for name, header, rows in sheets:\n        page = book.create_sheet(name[:31])\n        page.append(header)\n        for row in rows:\n            page.append(row)\n    buffer = io.BytesIO()\n    book.save(buffer)\n    return buffer.getvalue()\n\n\ndef excel_sheets(res, kind, measure, seg=ALL):\n    vintages, R, weight = matrix(res, kind, measure, seg)\n    steps, reached = average_steps(R, weight)\n    P, _ = projected(R, steps)\n    k = R.shape[1]\n    header = ["Поколение", "Кредитов" if measure == "count" else "Выдано"] + [f"MOB {m}" for m in range(k)]\n\n    def grid(A):\n        return [[month_name(v), float(weight[i])] + [None if np.isnan(x) else round(float(x), 6) for x in A[i]]\n                for i, v in enumerate(vintages)]\n\n    sheets = [("Факт", header, grid(R)), ("Факт + прогноз", header, grid(P)),\n              ("Средняя кривая", ["MOB", "Шаг", "Накоплено", "Поколений дошло"],\n               [[m, round(float(steps[m]), 6), round(float(c), 6), int(reached[m])]\n                for m, c in enumerate(typical_curve(steps))])]\n    tr = res["transitions"].filter((pl.col("group") == KINDS[kind]["group"]) &amp; (pl.col("seg") == seg)).sort("from", "to")\n    sheets.append(("Переходы", ["Из", "В", "Кредитов", "Сумма (начало)", "Сумма (через месяц)"],\n                   [[r["from"], r["to"], r["count"], r["amount"], r["next_amount"]] for r in tr.iter_rows(named=True)]))\n    return sheets\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-5. fake.py', 'category': 'programming', 'order': 5, 'summary': "Fake data in the bank's shape (a bad 2024 and a bad December are planted), to see the pages before the real file is there.", 'content': '<p>Step 5 of 11. Save as <code>vintage/fake.py</code>.</p>\n<h3>fake.py</h3>\n<pre><code class="language-python">"""\nFake data in the bank\'s shape, to see the pages before the real file exists:\n\n    python manage.py build_vintage --fake\n\nwrites datasets/vintage/input/fake.parquet (only if there is no other input file) and builds.\nDelete fake.parquet when the real file is in the folder.\n\nWhat is planted, so you can check the pages find it:\n  * loans issued from March to December 2024 go overdue twice as often (a bad policy year);\n  * loans issued in December are 30% worse (holiday lending);\n  * a few loans are restructured into category 3 without being 90+ (NPL ≠ 90+);\n  * loans issued in 2019 appear from the first month (no start of history);\n  * some loans have two rows in a month (two accounts), and some categories are 0;\n  * like the bank\'s file, 2020–2021 are QUARTERLY: 01.01.2020, 01.04.2020 … 01.01.2022, then monthly;\n  * two passports: 40% «vtorichka», which goes overdue 1.5 times as often as «pervichka».\n"""\nimport datetime as dt\n\nimport numpy as np\nimport polars as pl\n\n\ndef first_of(month_index):\n    return dt.date(2019 + month_index // 12, month_index % 12 + 1, 1)\n\n\ndef make(path, seed=7, last=(2026, 9), monthly_from=dt.date(2022, 1, 1)):\n    rng = np.random.default_rng(seed)\n    n_months = (last[0] - 2019) * 12 + last[1]          # month 0 = Jan 2019\n    issue_m, amount, term = [], [], []\n    for m in range(n_months):\n        season = {12: 1.3, 1: 0.8}.get(m % 12 + 1, 1.0)\n        n = int(500 * (1 + 0.012 * m) * season)\n        issue_m += [m] * n\n        amount += list(rng.lognormal(np.log(30e6), 0.6, n))\n        term += list(rng.choice([12, 24, 36], n))\n    issue_m, amount, term = np.array(issue_m), np.array(amount), np.array(term)\n    n = len(issue_m)\n    risk = np.ones(n)\n    passport = np.where(rng.random(n) &lt; 0.4, "vtorichka", "pervichka")\n    issued = [first_of(m) for m in range(n_months)]\n    for i, m in enumerate(range(n_months)):\n        d = issued[m]\n        factor = 1.0\n        if dt.date(2024, 3, 1) &lt;= d &lt;= dt.date(2024, 12, 1):\n            factor *= 2.0\n        if d.year == 2021:\n            factor *= 0.8\n        if d.month == 12:\n            factor *= 1.3\n        risk[issue_m == m] = factor\n    risk = risk * np.where(passport == "vtorichka", 1.5, 1.0)\n\n    dpd = np.zeros(n)\n    alive = np.ones(n, dtype=bool)\n    restr = np.zeros(n)                                 # months left in a restructuring\n    rows = []\n    cure = {1: 0.5, 30: 0.25, 60: 0.12, 90: 0.03}\n    for m in range(n_months):\n        live = np.where(alive &amp; (issue_m &lt;= m))[0]\n        age = m - issue_m[live]\n        # repaid, prepaid, written off\n        done = (age &gt;= term[live]) | (rng.random(len(live)) &lt; 0.012) | (dpd[live] &gt;= 450)\n        alive[live[done]] = False\n        live, age = live[~done], age[~done]\n        if m &lt; 11:                                      # 2019: issued, but the data starts with 01.01.2020\n            continue\n        d = dpd[live]\n        new_dpd = d.copy()\n        p_in = 0.03 * risk[live] * np.where(age &lt; 2, 0.3, 1.0)\n        start = (d == 0) &amp; (rng.random(len(live)) &lt; p_in)\n        new_dpd[start] = 15\n        late = d &gt; 0\n        p_cure = np.select([d &gt;= 90, d &gt;= 60, d &gt;= 30], [cure[90], cure[60], cure[30]], cure[1])\n        cured = late &amp; (rng.random(len(live)) &lt; p_cure)\n        new_dpd[late &amp; cured] = 0\n        new_dpd[late &amp; ~cured] = d[late &amp; ~cured] + 30\n        dpd[live] = new_dpd\n        r = restr[live]\n        newly = (new_dpd == 0) &amp; (r == 0) &amp; (rng.random(len(live)) &lt; 0.002)\n        r[newly] = 6\n        r[r &gt; 0] -= 1\n        restr[live] = r\n        cat = np.select([new_dpd &gt;= 270, new_dpd &gt;= 180, new_dpd &gt;= 90, new_dpd &gt;= 30], [5, 4, 3, 2], 1)\n        cat = np.where((r &gt; 0) &amp; (cat &lt; 3), 3, cat)\n        cat = np.where((cat == 1) &amp; (rng.random(len(live)) &lt; 0.05), 0, cat)        # 0 means 1\n        balance = amount[live] * np.clip(1 - age / term[live], 0.02, 1)\n        report = first_of(m + 1)                        # the 1st of the NEXT month\n        if report &lt; monthly_from and report.month not in (1, 4, 7, 10):\n            continue                                    # quarterly years: no file for this month\n        rows.append(pl.DataFrame({          # the bank\'s column names\n            "report_date": [report] * len(live), "anketa": live + 100000,\n            "valuedate": [issued[k] + dt.timedelta(days=int(k % 27)) for k in issue_m[live]],\n            "maks_dni": new_dpd.astype(int), "npl_category": cat.astype(int), "brutto_95_summa": balance.round(2),\n            "given_amount": amount[live].round(2), "passport": passport[live],\n        }))\n    df = pl.concat(rows)\n    twice = df.sample(fraction=0.01, seed=seed).with_columns(pl.col("brutto_95_summa") * 0.1)\n    df = pl.concat([df, twice])\n    path.parent.mkdir(parents=True, exist_ok=True)\n    df.write_parquet(path)\n    return df.height\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-6. management/commands/build_vintage.py', 'category': 'programming', 'order': 6, 'summary': 'The command that does the heavy work in its own process: python manage.py build_vintage (--fake for fake data).', 'content': '<p>Step 6 of 11. Save as <code>vintage/management/commands/build_vintage.py</code>.</p>\n<h3>management/commands/build_vintage.py</h3>\n<pre><code class="language-python">"""\nBuilds the vintage analysis from datasets/vintage/input/*.parquet into datasets/vintage/result/.\nThe page\'s «Пересчитать» button starts this command as its own process; you can also run it\nby hand (or monthly from a systemd timer, like build_portfel):\n\n    python manage.py build_vintage\n    python manage.py build_vintage --fake      # first write fake data (only if the folder is empty)\n"""\nimport datetime\nimport json\nimport os\nimport traceback\n\nfrom django.core.management.base import BaseCommand, CommandError\n\nfrom vintage import fake, process\n\n\ndef write_status(**fields):\n    process.BASE.mkdir(parents=True, exist_ok=True)\n    process.STATUS_FILE.write_text(json.dumps(fields, ensure_ascii=False))\n\n\nclass Command(BaseCommand):\n    help = "Build the vintage analysis (triangles, transitions) from the input parquet files."\n\n    def add_arguments(self, p):\n        p.add_argument("--fake", action="store_true", help="write fake input data first, if there is none")\n\n    def handle(self, *a, **o):\n        def log(msg):\n            self.stdout.write(str(msg))\n            self.stdout.flush()\n\n        started = datetime.datetime.now().isoformat(timespec="seconds")\n        write_status(running=True, started=started, pid=os.getpid())\n        try:\n            if o["fake"] and not process.input_files():\n                rows = fake.make(process.INPUT_DIR / "fake.parquet")\n                log(f"fake data written: {rows:,} rows")\n            meta = process.build(log=log)\n        except Exception as e:\n            write_status(running=False, started=started, error=f"{type(e).__name__}: {e}",\n                         trace=traceback.format_exc()[-3000:])\n            raise CommandError(str(e))\n        write_status(running=False, started=started, finished=meta["built_at"])\n        self.stdout.write(self.style.SUCCESS(f"vintage built: {meta[\'loans\']:,} loans, "\n                                             f"{meta[\'first_month\']} … {meta[\'last_month\']}"))\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-7. views.py', 'category': 'programming', 'order': 7, 'summary': 'The views: the page, the button that starts the command, Excel, the plan form.', 'content': '<p>Step 7 of 11. Save as <code>vintage/views.py</code>.</p>\n<h3>views.py</h3>\n<pre><code class="language-python">"""\nThe pages of the vintage app. Every view is short: it reads the address, asks process.py\nfor the numbers and gives them to a template.\n\n    /vintage/?kind=dpd90&amp;measure=amount&amp;seg=all\n                                            the analysis (kind: dpd30, dpd60, dpd90, npl;\n                                            measure: amount, count; seg: all or a passport)\n    /vintage/plan/?kind=dpd90&amp;lending=…     the business plan for the next 12 months\n    /vintage/excel/?kind=…&amp;measure=…        everything of the analysis in Excel\n    /vintage/rebuild/  (POST)               starts `manage.py build_vintage` in its own process\n\nThe heavy work (tens of millions of rows) is never done inside a page: the build runs as\nits own process and the pages read only its small results.\n"""\nimport json\nimport os\nimport subprocess\nimport sys\n\nfrom django.conf import settings\nfrom django.contrib import messages\nfrom django.contrib.auth.decorators import login_required\nfrom django.http import HttpResponse\nfrom django.shortcuts import redirect, render\nfrom django.views.decorators.http import require_POST\n\nfrom . import process\n\n\ndef chosen(request):\n    kind = request.GET.get("kind")\n    measure = request.GET.get("measure")\n    return (kind if kind in process.KINDS else "dpd90",\n            measure if measure in process.MEASURES else "amount")\n\n\ndef chosen_seg(request, res):\n    """?seg=vtorichka if that passport exists in the results, otherwise all passports."""\n    seg = request.GET.get("seg")\n    keys = [s["key"] for s in process.segments(res)] if res else []\n    return seg if seg in keys else process.ALL\n\n\ndef pid_alive(pid):\n    if not pid or os.name == "nt":          # on Windows os.kill(pid, 0) would KILL the process\n        return True\n    try:\n        os.kill(pid, 0)\n    except ProcessLookupError:\n        return False\n    except PermissionError:\n        return True\n    return True\n\n\ndef build_status():\n    """{\'running\': …, \'started\': …, \'error\': …} from status.json; a dead \'running\' becomes an error."""\n    try:\n        status = json.loads(process.STATUS_FILE.read_text())\n    except (FileNotFoundError, ValueError):\n        return {}\n    if status.get("running") and not pid_alive(status.get("pid")):\n        status = {"running": False, "started": status.get("started"),\n                  "error": "расчёт остановлен системой (часто — нехватка памяти). Смотрите datasets/vintage/build.log"}\n    return status\n\n\n@login_required\ndef home(request):\n    kind, measure = chosen(request)\n    group = process.KINDS[kind]["group"]\n    res = process.results()\n    seg = chosen_seg(request, res)\n    context = {"status": build_status(), "kind": kind, "measure": measure, "seg": seg,\n               "kinds": process.KINDS, "measures": process.MEASURES, "input_dir": process.INPUT_DIR,\n               "label": process.KINDS[kind]["label"], "measure_name": process.MEASURES[measure], "res": res}\n    if res:\n        vintages, R, weight = process.matrix(res, kind, measure, seg)\n        steps, reached = process.average_steps(R, weight)\n        P, proj = process.projected(R, steps)\n        mobs, rows = process.triangle_table(vintages, R, P, proj)\n        found, ref = process.insights(vintages, R, weight, steps, kind, measure)\n        meta = res["meta"]\n        context.update({\n            "meta": meta, "mobs": mobs, "rows": rows, "insights": found, "ref": ref,\n            "curves": process.curves_svg(vintages, R, weight, steps, res["meta"]["last_month"]),\n            "transitions": process.transitions_table(res, group, measure, seg),\n            "early": process.early_signal(res, "npl" if group == "npl" else "dpd90", seg),\n            "comparison": process.compare(res, kind, measure),\n            "segments": [dict(s, loans_text=f"{s[\'loans\']:,}".replace(",", " ")) for s in process.segments(res)],\n            "seg_label": process.segment_label(res, seg),\n            "season": process.seasonality(vintages, R, weight, ref),\n            "vintage_count": len(vintages),\n            "loans": f"{process.loans_in_vintages(res, seg):,}".replace(",", " "),\n            "migration_months": process.MIGRATION_MONTHS, "recent": process.RECENT_VINTAGES,\n            "early_mob": process.EARLY_MOB, "late_mob": process.LATE_MOB,\n        })\n    return render(request, "vintage/page.html", context)\n\n\n@login_required\n@require_POST\ndef rebuild(request):\n    if build_status().get("running"):\n        messages.info(request, "Расчёт уже идёт.")\n        return redirect("vintage")\n    process.BASE.mkdir(parents=True, exist_ok=True)\n    manage = os.path.join(settings.BASE_DIR, "manage.py")\n    log = open(process.LOG_FILE, "w")\n    options = {"creationflags": subprocess.CREATE_NEW_PROCESS_GROUP} if os.name == "nt" else {"start_new_session": True}\n    proc = subprocess.Popen([sys.executable, manage, "build_vintage"], cwd=settings.BASE_DIR,\n                            stdout=log, stderr=subprocess.STDOUT, **options)\n    process.STATUS_FILE.write_text(json.dumps({"running": True, "pid": proc.pid, "started": "только что"}))\n    messages.success(request, "Расчёт запущен. Страница обновится сама, когда он закончится.")\n    return redirect("vintage")\n\n\n@login_required\ndef excel(request):\n    kind, measure = chosen(request)\n    res = process.results()\n    if not res:\n        return redirect("vintage")\n    seg = chosen_seg(request, res)\n    data = process.xlsx(process.excel_sheets(res, kind, measure, seg))\n    name = f"vintage_{seg}_{kind}_{measure}_{res[\'meta\'][\'last_month\']:%Y-%m}.xlsx"\n    response = HttpResponse(data, content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")\n    response["Content-Disposition"] = f\'attachment; filename="{name}"\'\n    return response\n\n\ndef number(text, default):\n    """\'36 599,5\' or \'36599.5\' → 36599.5; anything else → default."""\n    try:\n        return float(str(text).replace(" ", "").replace("\\xa0", "").replace(",", "."))\n    except ValueError:\n        return default\n\n\n@login_required\ndef plan(request):\n    kind = request.GET.get("kind") if request.GET.get("kind") in ("dpd90", "npl") else "dpd90"\n    res = process.results()\n    if not res:\n        return redirect("vintage")\n    seg = chosen_seg(request, res)\n    default = process.default_lending(res, kind, seg) / process.AMOUNT_DIVISOR\n    lending = max(0.0, number(request.GET.get("lending", ""), default))\n    growth = number(request.GET.get("growth", ""), 0.0)\n    rows = process.plan(res, kind, lending * process.AMOUNT_DIVISOR, growth / 100, seg)\n    stock = process.markov(res, process.KINDS[kind]["group"], lending * process.AMOUNT_DIVISOR, growth / 100, seg)\n\n    if request.GET.get("excel"):\n        sheets = [("План", ["Месяц", "Выдача", "Новые из текущего портфеля", "Новые из новой выдачи", "Всего", "Накоплено"],\n                   [[r["month"], r["lending"], r["book"], r["new"], r["total"], r["cum"]] for r in rows]),\n                  ("Доля в портфеле", ["Месяц", "Портфель", "Плохой остаток", "Доля", "Факт/прогноз"],\n                   [[r["month"], r["total"], r["bad"], r["share"], "факт" if r["fact"] else "прогноз"] for r in stock])]\n        response = HttpResponse(process.xlsx(sheets),\n                                content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")\n        response["Content-Disposition"] = f\'attachment; filename="vintage_plan_{seg}_{kind}.xlsx"\'\n        return response\n\n    top = max([r["total"] for r in rows] + [1])\n    shown = [{"month": f"{r[\'month\']:%m.%Y}", "lending": process.money(r["lending"]), "book": process.money(r["book"]),\n              "new": process.money(r["new"]), "total": process.money(r["total"]), "cum": process.money(r["cum"]),\n              "bar_book": round(r["book"] / top * 100), "bar_new": round(r["new"] / top * 100)} for r in rows]\n    year = sum(r["total"] for r in rows)\n    lent = sum(r["lending"] for r in rows)\n    return render(request, "vintage/plan.html", {\n        "kind": kind, "label": process.KINDS[kind]["label"], "meta": res["meta"], "rows": shown,\n        "seg": seg, "seg_label": process.segment_label(res, seg), "segments": process.segments(res),\n        "lending": process.num(lending, 1), "default": process.num(default, 1), "growth": process.num(growth, 1),\n        "unit": process.AMOUNT_UNIT, "months": process.PLAN_MONTHS,\n        "year_total": process.money(year), "year_lent": process.money(lent),\n        "year_book": process.money(sum(r["book"] for r in rows)), "year_new": process.money(sum(r["new"] for r in rows)),\n        "stock": [{"month": f"{r[\'month\']:%m.%Y}", "share": process.pct(r["share"]), "bad": process.money(r["bad"]),\n                   "total": process.money(r["total"]), "fact": r["fact"]} for r in stock],\n        "query": request.GET.urlencode(),\n    })\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-8. templates/vintage/style.html', 'category': 'programming', 'order': 8, 'summary': 'The look (Kapitalbank colours), shared by both pages.', 'content': '<p>Step 8 of 11. Save as <code>vintage/templates/vintage/style.html</code>.</p>\n<h3>templates/vintage/style.html</h3>\n<pre><code class="language-html">{% comment %}\n  The look of the vintage pages (page.html, plan.html) — the same Kapitalbank palette as\n  the collateral app: yellow leads, charcoal second, red only for problems.\n  Everything sits under .vtg so it never touches the rest of the site.\n{% endcomment %}\n&lt;style&gt;\n  .vtg{--ink:#0B0B0C;--soft:#2A2A2E;--gold:#F2C230;--gd:#C9971A;--gtext:#8C6A12;\n       --rule:#E4E1D8;--paper:#FAF8F2;--muted:#8A867C;--bad:#B3341F;color:var(--ink)}\n  .vtg a{color:inherit}\n  .vtg .hero{background:var(--ink);color:#fff;border-radius:12px;padding:22px 26px;margin-bottom:20px}\n  .vtg .hero .eyebrow{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold)}\n  .vtg .hero h1{font-weight:500;font-size:26px;margin:6px 0 12px}\n  .vtg .hero h1 i{color:var(--gold);margin-right:10px}\n  .vtg .hero .chip{background:transparent;color:#fff;border-color:#55524B}\n  .vtg .hero .chip.on{background:var(--gold);color:var(--ink);border-color:var(--gold)}\n  .vtg .hero .lab{font-size:11px;color:#B9B5AB;margin-right:8px;text-transform:uppercase;letter-spacing:.08em}\n  .vtg .btn-go{background:var(--gold);border:none;color:var(--ink);font-weight:600}\n  .vtg .btn-go:hover{background:var(--gd);color:var(--ink)}\n  .vtg .btn-line{border:1px solid var(--rule);background:#fff;color:var(--ink)}\n  .vtg .btn-line:hover{border-color:var(--gold)}\n  .vtg .box{background:#fff;border:1px solid var(--rule);border-radius:12px;margin-bottom:20px}\n  .vtg .box-head{background:var(--paper);border-bottom:1px solid var(--rule);border-radius:12px 12px 0 0;\n       padding:10px 16px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--gtext);\n       display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}\n  .vtg .box-head i{margin-right:8px;color:var(--gd)}\n  .vtg .box-head .hint{letter-spacing:0;text-transform:none;color:var(--muted);font-size:12px}\n  .vtg .kpi{background:#fff;border:1px solid var(--rule);border-radius:12px;padding:12px 14px;height:100%}\n  .vtg .kpi .l{font-size:10.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}\n  .vtg .kpi .l i{color:var(--gd);margin-right:6px}\n  .vtg .kpi .v{font-size:21px;font-weight:600;margin-top:4px;white-space:nowrap}\n  .vtg .kpi .n{font-size:12px;color:var(--muted)}\n  .vtg .chip{display:inline-block;border:1px solid var(--rule);border-radius:20px;padding:3px 12px;\n       font-size:12.5px;text-decoration:none;margin:0 6px 6px 0;background:#fff}\n  .vtg .chip:hover{border-color:var(--gold)}\n  .vtg .chip.on{border-color:var(--gold);background:#FFF6D6;font-weight:600}\n  .vtg .insights{margin:0;padding:12px 16px 12px 36px;font-size:14px;line-height:1.55}\n  .vtg .insights li{margin-bottom:6px}\n  .vtg table{font-size:13px;margin:0}\n  .vtg th{font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);font-weight:600;white-space:nowrap}\n  .vtg td.m,.vtg th.m{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}\n  .vtg .muted{color:var(--muted)}\n  .vtg .warn{color:var(--bad)}\n  .vtg .nothing{padding:14px 16px;color:var(--muted);font-size:13px}\n  /* the triangle */\n  .vtg .tri-wrap{overflow:auto;max-height:640px}\n  .vtg table.tri{border-collapse:separate;border-spacing:0;font-size:11.5px}\n  .vtg table.tri th,.vtg table.tri td{padding:3px 5px;text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}\n  .vtg table.tri thead th{position:sticky;top:0;background:var(--paper);z-index:2;border-bottom:1px solid var(--rule)}\n  .vtg table.tri .v{position:sticky;left:0;background:#fff;z-index:1;text-align:left;font-weight:600;border-right:1px solid var(--rule)}\n  .vtg table.tri thead .v{z-index:3;background:var(--paper)}\n  .vtg table.tri tr.ys td{border-top:2px solid var(--ink)}\n  .vtg table.tri td.p{font-style:italic;opacity:.75;\n       background-image:repeating-linear-gradient(135deg,rgba(0,0,0,.07) 0 2px,transparent 2px 6px)!important}\n  .vtg table.tri td.gap,.vtg .key.gap{background:#EFEDE6}\n  .vtg .key{display:inline-block;width:22px;height:12px;border:1px solid var(--rule);vertical-align:middle;margin:0 4px 0 10px}\n  .vtg .key.p{background-image:repeating-linear-gradient(135deg,rgba(0,0,0,.18) 0 2px,transparent 2px 6px)}\n  /* transitions */\n  .vtg table.mig td,.vtg table.mig th{text-align:right;padding:4px 7px;font-variant-numeric:tabular-nums}\n  .vtg table.mig td.s,.vtg table.mig th.s{text-align:left;font-weight:600}\n  .vtg table.mig td.d{font-weight:700}\n  .vtg .flow{display:flex;justify-content:space-between;gap:10px;padding:7px 16px;border-top:1px solid var(--rule);font-size:13.5px}\n  .vtg .flow b{white-space:nowrap}\n  /* bars */\n  .vtg .bar{height:9px;border-radius:3px;background:var(--gold);min-width:2px;display:inline-block;vertical-align:middle}\n  .vtg .bar.dark{background:var(--soft)}\n  /* the curves picture */\n  .vtg svg.curves{width:100%;height:auto;display:block}\n  .vtg svg.curves .grid{stroke:var(--rule);stroke-width:1}\n  .vtg svg.curves .axis{stroke:var(--muted);stroke-width:1}\n  .vtg svg.curves text{font-size:11px;fill:var(--muted)}\n  .vtg svg.curves polyline{fill:none;stroke-width:2.2;stroke-linejoin:round}\n  .vtg svg.curves polyline.typ{stroke:var(--ink);stroke-dasharray:6 5;stroke-width:2}\n  .vtg .legend span{display:inline-block;margin:0 14px 4px 0;font-size:12.5px}\n  .vtg .legend i{display:inline-block;width:18px;height:3px;vertical-align:middle;margin-right:6px}\n  .vtg .legend i.typ{background:repeating-linear-gradient(90deg,var(--ink) 0 6px,transparent 6px 10px)}\n  .vtg details.help summary{cursor:pointer;color:var(--gtext);font-size:13.5px}\n  .vtg details.help{font-size:13.5px;line-height:1.55}\n  .vtg .tag{font-size:10.5px;border:1px solid var(--rule);border-radius:10px;padding:1px 7px;color:var(--muted)}\n  .vtg .box-head .hint{overflow-wrap:anywhere;min-width:0}\n  .vtg .insights,.vtg .flow span{overflow-wrap:anywhere}\n  @media (max-width:576px){.vtg{padding-left:12px!important;padding-right:12px!important}\n       .vtg .kpi .v{font-size:17px;white-space:normal}.vtg .hero h1{font-size:21px}}\n  @media print{.vtg .no-print{display:none!important}.vtg .tri-wrap{max-height:none;overflow:visible}}\n&lt;/style&gt;\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-9. templates/vintage/page.html', 'category': 'programming', 'order': 9, 'summary': 'The analysis: insights, curves, the triangle, transitions, early signal, issue month, «how to read».', 'content': '<p>Step 9 of 11. Save as <code>vintage/templates/vintage/page.html</code>.</p>\n<h3>templates/vintage/page.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  The vintage page. One template for every analysis: kind (30+/60+/90+/NPL) and measure\n  (по сумме / по количеству) are words in the address, so every view has its own link.\n  Every number arrives already formatted from process.py; the template only places it.\n  No JavaScript: while a build is running the page reloads itself with a &lt;meta refresh&gt;.\n{% endcomment %}\n\n{% block extra_css %}\n{% include "vintage/style.html" %}\n{% if status.running %}&lt;meta http-equiv="refresh" content="15"&gt;{% endif %}\n{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="vtg container-fluid px-4 py-4"&gt;\n\n  {% if messages %}{% for m in messages %}&lt;div class="alert alert-{% if m.tags == \'error\' %}danger{% else %}{{ m.tags|default:\'info\' }}{% endif %} no-print"&gt;{{ m }}&lt;/div&gt;{% endfor %}{% endif %}\n\n  {# ── the build bar: when the results are from, and the button that recalculates ── #}\n  &lt;div class="box no-print"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-layer-group"&gt;&lt;/i&gt;Данные анализа&lt;/span&gt;\n      &lt;span class="hint"&gt;файлы: {{ input_dir }}&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="p-3 d-flex flex-wrap justify-content-between align-items-center gap-3"&gt;\n      &lt;div&gt;\n        {% if status.running %}\n          &lt;div class="fw-semibold"&gt;&lt;i class="fa-solid fa-spinner fa-spin me-2" style="color:#C9971A"&gt;&lt;/i&gt;Идёт расчёт (начат {{ status.started }})&lt;/div&gt;\n          &lt;div class="small text-muted"&gt;Страница обновляется сама каждые 15 секунд.&lt;/div&gt;\n        {% elif res %}\n          &lt;div class="small text-muted"&gt;Рассчитано&lt;/div&gt;\n          &lt;div class="fs-5 fw-semibold"&gt;&lt;i class="fa-regular fa-clock me-2" style="color:#C9971A"&gt;&lt;/i&gt;{{ meta.built_at|slice:":10" }} {{ meta.built_at|slice:"11:16" }}\n            &lt;span class="small text-muted fw-normal"&gt;· {{ meta.seconds }} с · файлы: {{ meta.files|join:", " }}&lt;/span&gt;&lt;/div&gt;\n        {% else %}\n          &lt;div class="fw-semibold"&gt;Анализ ещё не рассчитан.&lt;/div&gt;\n          &lt;div class="small text-muted"&gt;Положите parquet-файл(ы) в папку выше и нажмите «Пересчитать».\n            Колонки: date, anketa, issue_date, maks_dni, npl_category, portfel_amount (названия меняются в process.py → COLUMNS).&lt;/div&gt;\n        {% endif %}\n        {% if status.error %}&lt;div class="small mt-1 warn"&gt;&lt;i class="fa-solid fa-circle-exclamation me-1"&gt;&lt;/i&gt;Последний расчёт не удался: {{ status.error }}&lt;/div&gt;{% endif %}\n      &lt;/div&gt;\n      &lt;form method="post" action="{% url \'vintage-rebuild\' %}"&gt;{% csrf_token %}\n        &lt;button class="btn btn-go" {% if status.running %}disabled{% endif %}&gt;&lt;i class="fa-solid fa-rotate me-2"&gt;&lt;/i&gt;Пересчитать&lt;/button&gt;\n      &lt;/form&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {% if res %}\n  {# ── the header: which analysis, which measure ── #}\n  &lt;div class="hero"&gt;\n    &lt;div class="eyebrow"&gt;Винтажный анализ · {{ seg_label }} · {{ meta.first_month|date:"m.Y" }} — {{ meta.last_month|date:"m.Y" }}&lt;/div&gt;\n    &lt;h1&gt;&lt;i class="fa-solid fa-chart-line"&gt;&lt;/i&gt;{{ label }} &lt;span style="font-size:16px;color:#B9B5AB"&gt;{{ measure_name }}&lt;/span&gt;&lt;/h1&gt;\n    &lt;div&gt;&lt;span class="lab"&gt;Анализ&lt;/span&gt;\n      {% for key, k in kinds.items %}&lt;a class="chip {% if key == kind %}on{% endif %}" href="?kind={{ key }}&amp;measure={{ measure }}&amp;seg={{ seg }}"&gt;{{ k.label }}&lt;/a&gt;{% endfor %}\n    &lt;/div&gt;\n    &lt;div&gt;&lt;span class="lab"&gt;Считать&lt;/span&gt;\n      {% for key, name in measures.items %}&lt;a class="chip {% if key == measure %}on{% endif %}" href="?kind={{ kind }}&amp;measure={{ key }}&amp;seg={{ seg }}"&gt;{{ name }}&lt;/a&gt;{% endfor %}\n    &lt;/div&gt;\n    &lt;div&gt;&lt;span class="lab"&gt;Паспорт&lt;/span&gt;\n      {% for s in segments %}&lt;a class="chip {% if s.key == seg %}on{% endif %}" href="?kind={{ kind }}&amp;measure={{ measure }}&amp;seg={{ s.key|urlencode }}"&gt;{{ s.label }} &lt;span style="opacity:.6"&gt;{{ s.loans_text }}&lt;/span&gt;&lt;/a&gt;{% endfor %}\n      &lt;a class="chip no-print" href="{% url \'vintage-plan\' %}?kind={% if kind == \'npl\' %}npl{% else %}dpd90{% endif %}&amp;seg={{ seg|urlencode }}"&gt;&lt;i class="fa-solid fa-bullseye me-1"&gt;&lt;/i&gt;Бизнес-план&lt;/a&gt;\n      &lt;a class="chip no-print" href="{% url \'vintage-excel\' %}?kind={{ kind }}&amp;measure={{ measure }}&amp;seg={{ seg|urlencode }}"&gt;&lt;i class="fa-solid fa-file-excel me-1"&gt;&lt;/i&gt;Excel&lt;/a&gt;\n      &lt;a class="chip no-print" href="javascript:window.print()"&gt;&lt;i class="fa-solid fa-print me-1"&gt;&lt;/i&gt;Печать&lt;/a&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  &lt;div class="row g-3 mb-4"&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-file-invoice"&gt;&lt;/i&gt;Кредитов в поколениях&lt;/div&gt;&lt;div class="v"&gt;{{ loans }}&lt;/div&gt;&lt;div class="n"&gt;выданы с {{ meta.first_month|date:"m.Y" }}&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-layer-group"&gt;&lt;/i&gt;Поколений&lt;/div&gt;&lt;div class="v"&gt;{{ vintage_count }}&lt;/div&gt;&lt;div class="n"&gt;по месяцу выдачи&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-ruler-horizontal"&gt;&lt;/i&gt;Сравниваем на&lt;/div&gt;&lt;div class="v"&gt;{{ ref }}-м месяце&lt;/div&gt;&lt;div class="n"&gt;жизни кредита&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-calendar"&gt;&lt;/i&gt;Последний месяц&lt;/div&gt;&lt;div class="v"&gt;{{ meta.last_month|date:"m.Y" }}&lt;/div&gt;&lt;div class="n"&gt;данные на конец месяца&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n  &lt;/div&gt;\n\n  {# ── the sentences ── #}\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-lightbulb"&gt;&lt;/i&gt;Что видно&lt;/span&gt;&lt;span class="hint"&gt;{{ seg_label }} · {{ label }}, {{ measure_name }}&lt;/span&gt;&lt;/div&gt;\n    {% if insights %}&lt;ul class="insights"&gt;{% for s in insights %}&lt;li&gt;{{ s }}&lt;/li&gt;{% endfor %}&lt;/ul&gt;\n    {% else %}&lt;div class="nothing"&gt;Слишком мало истории для выводов.&lt;/div&gt;{% endif %}\n  &lt;/div&gt;\n\n  {# ── the passports side by side ── #}\n  {% if comparison %}\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-code-compare"&gt;&lt;/i&gt;Паспорта рядом&lt;/span&gt;\n      &lt;span class="hint"&gt;{{ label }}, {{ measure_name }} — одинаковый возраст кредита&lt;/span&gt;&lt;/div&gt;\n    {% if comparison.sentence %}&lt;div class="px-3 pt-3 fw-semibold" style="font-size:14px"&gt;{{ comparison.sentence }}&lt;/div&gt;{% endif %}\n    &lt;div class="row g-0"&gt;\n      &lt;div class="col-xl-5"&gt;\n        &lt;div class="table-responsive"&gt;\n          &lt;table class="table table-sm mb-0 mt-2"&gt;\n            &lt;thead&gt;&lt;tr&gt;&lt;th class="ps-3"&gt;Паспорт&lt;/th&gt;&lt;th class="m"&gt;Кредитов&lt;/th&gt;\n              {% for m in comparison.mobs %}&lt;th class="m"&gt;{{ m }}-й мес.&lt;br&gt;&lt;span style="text-transform:none;letter-spacing:0"&gt;кривая / факт&lt;/span&gt;&lt;/th&gt;{% endfor %}&lt;/tr&gt;&lt;/thead&gt;\n            &lt;tbody&gt;{% for r in comparison.rows %}&lt;tr {% if r.key == seg %}style="background:#FFF6D6"{% endif %}&gt;\n              &lt;td class="ps-3 fw-semibold"&gt;&lt;a href="?kind={{ kind }}&amp;measure={{ measure }}&amp;seg={{ r.key|urlencode }}"&gt;{{ r.label }}&lt;/a&gt;&lt;/td&gt;\n              &lt;td class="m muted"&gt;{{ r.loans }}&lt;/td&gt;\n              {% for c in r.cells %}&lt;td class="m"&gt;&lt;b&gt;{{ c.curve }}&lt;/b&gt; &lt;span class="muted"&gt;/ {{ c.fact }}&lt;/span&gt;&lt;/td&gt;{% endfor %}&lt;/tr&gt;{% endfor %}&lt;/tbody&gt;\n          &lt;/table&gt;\n        &lt;/div&gt;\n        &lt;div class="p-2 px-3 small muted"&gt;Кривая — как ожидается, будет стареть поколение, выданное сегодня (по {{ recent }} новейшим поколениям паспорта).\n          Факт — среднее {{ recent }} последних поколений, которые уже дожили до этого месяца.&lt;/div&gt;\n      &lt;/div&gt;\n      &lt;div class="col-xl-7 p-3"&gt;{% include "vintage/chart.html" with c=comparison.chart %}&lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n  {% endif %}\n\n  {# ── the picture ── #}\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-chart-line"&gt;&lt;/i&gt;Кривые по году выдачи&lt;/span&gt;\n      &lt;span class="hint"&gt;ось X — месяц жизни кредита, ось Y — доля, накопленная к этому месяцу&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="p-3"&gt;\n      {% include "vintage/chart.html" with c=curves %}\n      &lt;div class="small muted mt-1"&gt;Пунктир — типичная кривая (по {{ recent }} новейшим поколениям), на ней строится прогноз.&lt;/div&gt;\n      &lt;div class="small muted mt-1"&gt;Линия года обрывается, когда меньше половины его поколений дожили до этого месяца. Чем выше и круче линия — тем хуже выдача того года.&lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {# ── the triangle ── #}\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-table-cells"&gt;&lt;/i&gt;Треугольник поколений, %&lt;/span&gt;\n      &lt;span class="hint"&gt;строка — месяц выдачи, столбец — месяц жизни (MOB)\n        &lt;span class="key"&gt;&lt;/span&gt;факт &lt;span class="key p"&gt;&lt;/span&gt;прогноз{% if meta.missing_from %} &lt;span class="key gap"&gt;&lt;/span&gt;нет данных{% endif %}&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="tri-wrap"&gt;\n      &lt;table class="tri"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th class="v"&gt;Выдача&lt;/th&gt;{% for m in mobs %}&lt;th&gt;{{ m }}&lt;/th&gt;{% endfor %}&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for r in rows %}&lt;tr class="{% if r.year_start %}ys{% endif %}"&gt;&lt;td class="v"&gt;{{ r.vintage }}&lt;/td&gt;{% for c in r.cells %}{% if c.gap %}&lt;td class="gap"&gt;&lt;/td&gt;{% else %}&lt;td class="{% if c.proj %}p{% endif %}" style="background:{{ c.bg }};color:{{ c.fg }}"&gt;{{ c.text }}&lt;/td&gt;{% endif %}{% endfor %}&lt;/tr&gt;\n        {% endfor %}\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    &lt;div class="p-2 px-3 small muted"&gt;Читать по столбцу: одинаковый возраст — честное сравнение поколений. Читать по строке: как поколение стареет.\n      Штриховка — прогноз: последний факт строки плюс средний прирост этого месяца у {{ recent }} новейших поколений, которые до него дошли.\n      {% if meta.missing_from %}&lt;br&gt;С {{ meta.missing_from|date:"m.Y" }} по {{ meta.missing_to|date:"m.Y" }} данные поквартальные: у поколений тех лет значение есть только в месяцы среза, остальные клетки пустые — они не угадываются и не входят в средние.{% endif %}&lt;/div&gt;\n  &lt;/div&gt;\n\n  &lt;div class="row g-3"&gt;\n    {# ── transitions ── #}\n    &lt;div class="col-xl-6"&gt;\n      &lt;div class="box h-100"&gt;\n        &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-shuffle"&gt;&lt;/i&gt;Куда кредиты переходят за месяц, %&lt;/span&gt;\n          &lt;span class="hint"&gt;последние {{ migration_months }} мес., {{ measure_name }}&lt;/span&gt;&lt;/div&gt;\n        &lt;div class="table-responsive"&gt;\n          &lt;table class="table table-sm mig"&gt;\n            &lt;thead&gt;&lt;tr&gt;&lt;th class="s"&gt;Из \\ в&lt;/th&gt;{% for c in transitions.cols %}&lt;th&gt;{{ c }}&lt;/th&gt;{% endfor %}&lt;th&gt;Всего&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n            &lt;tbody&gt;{% for r in transitions.rows %}&lt;tr&gt;&lt;td class="s"&gt;{{ r.state }}&lt;/td&gt;{% for c in r.cells %}&lt;td class="{% if c.diag %}d{% endif %}" style="background:{{ c.bg }};color:{{ c.fg }}"&gt;{{ c.text }}&lt;/td&gt;{% endfor %}&lt;td class="muted"&gt;{{ r.total }}&lt;/td&gt;&lt;/tr&gt;{% endfor %}&lt;/tbody&gt;\n          &lt;/table&gt;\n        &lt;/div&gt;\n        {% for name, value in transitions.key %}&lt;div class="flow"&gt;&lt;span&gt;{{ name }}&lt;/span&gt;&lt;b&gt;{{ value }}&lt;/b&gt;&lt;/div&gt;{% endfor %}\n        &lt;div class="p-2 px-3 small muted"&gt;Строка = где кредит был, столбец = где он через месяц; «вышел» — погашен, списан или продан. Жирная диагональ — остался на месте.&lt;/div&gt;\n      &lt;/div&gt;\n    &lt;/div&gt;\n    {# ── early signal + seasonality ── #}\n    &lt;div class="col-xl-6"&gt;\n      &lt;div class="box"&gt;\n        &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-bell"&gt;&lt;/i&gt;Ранний сигнал&lt;/span&gt;\n          &lt;span class="hint"&gt;30+ на {{ early_mob }}-м мес. → {{ early.late_label|default:"" }} на {{ late_mob }}-м&lt;/span&gt;&lt;/div&gt;\n        {% if early %}\n        &lt;div class="p-3 pb-2" style="font-size:13.5px"&gt;\n          Связь &lt;b&gt;{{ early.strength }}&lt;/b&gt; (корреляция {{ early.r }}, по {{ early.n }} поколениям, по сумме).&lt;br&gt;\n          &lt;span class="muted"&gt;{{ early.formula }}&lt;/span&gt;\n        &lt;/div&gt;\n        {% if early.rows %}\n        &lt;table class="table table-sm mb-0"&gt;\n          &lt;thead&gt;&lt;tr&gt;&lt;th class="ps-3"&gt;Выдача&lt;/th&gt;&lt;th class="m"&gt;30+ на {{ early_mob }}-м&lt;/th&gt;&lt;th class="m"&gt;прогноз по сигналу&lt;/th&gt;&lt;th class="m pe-3"&gt;прогноз по кривой&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n          &lt;tbody&gt;{% for r in early.rows %}&lt;tr&gt;&lt;td class="ps-3"&gt;{{ r.vintage }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.early }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.by_signal }}&lt;/td&gt;&lt;td class="m pe-3"&gt;{{ r.by_curve }}&lt;/td&gt;&lt;/tr&gt;{% endfor %}&lt;/tbody&gt;\n        &lt;/table&gt;{% endif %}\n        &lt;div class="p-2 px-3 small muted"&gt;Если связь сильная, о поколении можно судить уже через {{ early_mob }} месяца — не дожидаясь года. Два прогноза рядом: если они сильно расходятся, поколение ведёт себя необычно.&lt;/div&gt;\n        {% else %}&lt;div class="nothing"&gt;Нужно хотя бы 8 поколений, доживших до {{ late_mob }}-го месяца.&lt;/div&gt;{% endif %}\n      &lt;/div&gt;\n      &lt;div class="box"&gt;\n        &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-calendar-days"&gt;&lt;/i&gt;Месяц выдачи&lt;/span&gt;&lt;span class="hint"&gt;{{ label }} на {{ ref }}-м месяце жизни&lt;/span&gt;&lt;/div&gt;\n        {% if season %}\n        &lt;table class="table table-sm mb-0"&gt;&lt;tbody&gt;\n          {% for s in season %}&lt;tr&gt;&lt;td class="ps-3" style="width:110px"&gt;{{ s.name }}&lt;/td&gt;&lt;td&gt;&lt;span class="bar" style="width:{{ s.bar }}%"&gt;&lt;/span&gt;&lt;/td&gt;&lt;td class="m pe-3" style="width:80px"&gt;{{ s.value }}&lt;/td&gt;&lt;/tr&gt;{% endfor %}\n        &lt;/tbody&gt;&lt;/table&gt;\n        {% else %}&lt;div class="nothing"&gt;Нужно хотя бы по 2 поколения на каждый календарный месяц.&lt;/div&gt;{% endif %}\n      &lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  {# ── for the people who ask «how do I read this?» ── #}\n  &lt;div class="box mt-3"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-circle-question"&gt;&lt;/i&gt;Как это читать&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="p-3"&gt;\n      &lt;details class="help"&gt;&lt;summary&gt;Что такое поколение и треугольник&lt;/summary&gt;\n        &lt;p class="mt-2"&gt;Поколение — все кредиты, выданные в один месяц. Каждое поколение отслеживается помесячно с момента выдачи (MOB — месяц жизни).\n          В клетке — доля поколения, которая &lt;b&gt;хотя бы раз&lt;/b&gt; была в «{{ label }}» к этому месяцу жизни. «Хотя бы раз» — чтобы кредиты, которые потом\n          списали или вылечили, не выпадали и старые поколения не выглядели чище, чем были.&lt;/p&gt;\n        &lt;p&gt;Общий процент NPL портфеля смешивает молодые кредиты (они ещё не успели испортиться) со старыми. Треугольник сравнивает поколения\n          в одинаковом возрасте — поэтому видно, стала ли выдача лучше или хуже.&lt;/p&gt;&lt;/details&gt;\n      &lt;details class="help mt-2"&gt;&lt;summary&gt;По сумме и по количеству&lt;/summary&gt;\n        &lt;p class="mt-2"&gt;По количеству — плохие кредиты / все кредиты поколения. По сумме — остаток кредита в месяц, когда он впервые стал плохим /\n          сумма, выданная поколению (given_amount). Делим на выданное, а не на текущий остаток: остаток уменьшается с погашениями, и доля росла бы сама.&lt;/p&gt;&lt;/details&gt;\n      &lt;details class="help mt-2"&gt;&lt;summary&gt;Как получается бизнес-план&lt;/summary&gt;\n        &lt;p class="mt-2"&gt;Молодые поколения дописываются средними приростами старых (штриховка в треугольнике). Плановая выдача каждого месяца идёт\n          по типичной кривой. Сумма двух частей — ожидаемые новые {{ label }} по месяцам. Вторая проверка — матрица переходов, применённая к сегодняшнему портфелю.&lt;/p&gt;&lt;/details&gt;\n      &lt;details class="help mt-2"&gt;&lt;summary&gt;Проверки данных&lt;/summary&gt;\n        &lt;table class="table table-sm mt-2" style="max-width:760px"&gt;{% for k, v in meta.checks.items %}&lt;tr&gt;&lt;td&gt;{{ k }}&lt;/td&gt;&lt;td class="m"&gt;{{ v }}&lt;/td&gt;&lt;/tr&gt;{% endfor %}&lt;/table&gt;&lt;/details&gt;\n    &lt;/div&gt;\n  &lt;/div&gt;\n  {% endif %}\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-10. templates/vintage/plan.html', 'category': 'programming', 'order': 10, 'summary': 'The business plan: expected new 90+ / NPL per month, and the second route (transitions).', 'content': '<p>Step 10 of 11. Save as <code>vintage/templates/vintage/plan.html</code>.</p>\n<h3>templates/vintage/plan.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  The business plan: expected NEW 90+ / NPL money per month for the next 12 months, from the\n  existing book (finished triangle rows) and from the planned lending (typical curve), plus the\n  second route — the transitions table applied to today\'s portfolio.\n  The form is a plain GET form: every plan has its own link.\n{% endcomment %}\n\n{% block extra_css %}{% include "vintage/style.html" %}{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="vtg container-fluid px-4 py-4"&gt;\n\n  &lt;div class="hero"&gt;\n    &lt;div class="eyebrow"&gt;&lt;a href="{% url \'vintage\' %}?kind={{ kind }}&amp;seg={{ seg|urlencode }}" style="color:#F2C230"&gt;Винтажный анализ&lt;/a&gt; · бизнес-план · {{ seg_label }}&lt;/div&gt;\n    &lt;h1&gt;&lt;i class="fa-solid fa-bullseye"&gt;&lt;/i&gt;{{ label }}: следующие {{ months }} месяцев&lt;/h1&gt;\n    &lt;div&gt;&lt;span class="lab"&gt;Что планируем&lt;/span&gt;\n      &lt;a class="chip {% if kind == \'dpd90\' %}on{% endif %}" href="?kind=dpd90&amp;seg={{ seg|urlencode }}"&gt;Просрочка 90+&lt;/a&gt;\n      &lt;a class="chip {% if kind == \'npl\' %}on{% endif %}" href="?kind=npl&amp;seg={{ seg|urlencode }}"&gt;NPL&lt;/a&gt;\n    &lt;/div&gt;\n    &lt;div&gt;&lt;span class="lab"&gt;Паспорт&lt;/span&gt;\n      {% for s in segments %}&lt;a class="chip {% if s.key == seg %}on{% endif %}" href="?kind={{ kind }}&amp;seg={{ s.key|urlencode }}"&gt;{{ s.label }}&lt;/a&gt;{% endfor %}\n    &lt;/div&gt;\n  &lt;/div&gt;\n\n  &lt;div class="box no-print"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-sliders"&gt;&lt;/i&gt;Плановая выдача&lt;/span&gt;\n      &lt;span class="hint"&gt;по умолчанию — средняя выдача «{{ seg_label }}» за последние 12 месяцев: {{ default }} {{ unit }}&lt;/span&gt;&lt;/div&gt;\n    &lt;form method="get" class="p-3 row g-3 align-items-end"&gt;\n      &lt;input type="hidden" name="kind" value="{{ kind }}"&gt;\n      &lt;input type="hidden" name="seg" value="{{ seg }}"&gt;\n      &lt;div class="col-sm-4 col-lg-3"&gt;&lt;label class="form-label small"&gt;Выдача в месяц, {{ unit }}&lt;/label&gt;\n        &lt;input class="form-control" name="lending" value="{{ lending }}"&gt;&lt;/div&gt;\n      &lt;div class="col-sm-4 col-lg-3"&gt;&lt;label class="form-label small"&gt;Рост выдачи, % в месяц&lt;/label&gt;\n        &lt;input class="form-control" name="growth" value="{{ growth }}"&gt;&lt;/div&gt;\n      &lt;div class="col-sm-4 col-lg-6 d-flex gap-2 flex-wrap"&gt;\n        &lt;button class="btn btn-go"&gt;&lt;i class="fa-solid fa-calculator me-2"&gt;&lt;/i&gt;Посчитать&lt;/button&gt;\n        &lt;a class="btn btn-line" href="?{{ query }}&amp;excel=1"&gt;&lt;i class="fa-solid fa-file-excel me-2"&gt;&lt;/i&gt;Excel&lt;/a&gt;\n        &lt;a class="btn btn-line" href="javascript:window.print()"&gt;&lt;i class="fa-solid fa-print me-2"&gt;&lt;/i&gt;Печать&lt;/a&gt;\n      &lt;/div&gt;\n    &lt;/form&gt;\n  &lt;/div&gt;\n\n  &lt;div class="row g-3 mb-4"&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-hand-holding-dollar"&gt;&lt;/i&gt;Выдача за {{ months }} мес.&lt;/div&gt;&lt;div class="v"&gt;{{ year_lent }}&lt;/div&gt;&lt;div class="n"&gt;{{ unit }}&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-triangle-exclamation"&gt;&lt;/i&gt;Новые {{ label }}&lt;/div&gt;&lt;div class="v warn"&gt;{{ year_total }}&lt;/div&gt;&lt;div class="n"&gt;{{ unit }}, всего за {{ months }} мес.&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-box-archive"&gt;&lt;/i&gt;Из текущего портфеля&lt;/div&gt;&lt;div class="v"&gt;{{ year_book }}&lt;/div&gt;&lt;div class="n"&gt;{{ unit }}&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n    &lt;div class="col-6 col-lg-3"&gt;&lt;div class="kpi"&gt;&lt;div class="l"&gt;&lt;i class="fa-solid fa-seedling"&gt;&lt;/i&gt;Из новой выдачи&lt;/div&gt;&lt;div class="v"&gt;{{ year_new }}&lt;/div&gt;&lt;div class="n"&gt;{{ unit }}&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;\n  &lt;/div&gt;\n\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-table"&gt;&lt;/i&gt;Сколько остатка впервые станет «{{ label }}», {{ unit }}&lt;/span&gt;\n      &lt;span class="hint"&gt;&lt;span class="bar dark" style="width:18px"&gt;&lt;/span&gt; текущий портфель &amp;nbsp; &lt;span class="bar" style="width:18px"&gt;&lt;/span&gt; новая выдача&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm mb-0"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th class="ps-3"&gt;Месяц&lt;/th&gt;&lt;th class="m"&gt;Выдача&lt;/th&gt;&lt;th class="m"&gt;Из портфеля&lt;/th&gt;&lt;th class="m"&gt;Из новой выдачи&lt;/th&gt;&lt;th class="m"&gt;Всего&lt;/th&gt;&lt;th style="width:30%"&gt;&lt;/th&gt;&lt;th class="m pe-3"&gt;Накоплено&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;{% for r in rows %}&lt;tr&gt;\n          &lt;td class="ps-3"&gt;{{ r.month }}&lt;/td&gt;&lt;td class="m muted"&gt;{{ r.lending }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.book }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.new }}&lt;/td&gt;\n          &lt;td class="m fw-semibold"&gt;{{ r.total }}&lt;/td&gt;\n          &lt;td&gt;&lt;span class="bar dark" style="width:{{ r.bar_book }}%"&gt;&lt;/span&gt;&lt;span class="bar" style="width:{{ r.bar_new }}%"&gt;&lt;/span&gt;&lt;/td&gt;\n          &lt;td class="m pe-3"&gt;{{ r.cum }}&lt;/td&gt;&lt;/tr&gt;{% endfor %}&lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    &lt;div class="p-2 px-3 small muted"&gt;Это поток: остаток, который &lt;b&gt;впервые&lt;/b&gt; дойдёт до «{{ label }}» в этом месяце. Из портфеля — поколения,\n      выданные с {{ meta.first_month|date:"m.Y" }}, идут дальше по своим строкам треугольника (штриховка). Из новой выдачи — каждый плановый месяц\n      идёт по типичной кривой. Кредиты, выданные раньше {{ meta.first_month|date:"m.Y" }}, сюда не входят.&lt;/div&gt;\n  &lt;/div&gt;\n\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-shuffle"&gt;&lt;/i&gt;Проверка вторым способом: доля в портфеле&lt;/span&gt;\n      &lt;span class="hint"&gt;матрица переходов последних 12 мес. × сегодняшний портфель + плановая выдача&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="table-responsive"&gt;\n      &lt;table class="table table-sm mb-0"&gt;\n        &lt;thead&gt;&lt;tr&gt;&lt;th class="ps-3"&gt;Месяц&lt;/th&gt;&lt;th class="m"&gt;Портфель, {{ unit }}&lt;/th&gt;&lt;th class="m"&gt;«{{ label }}», {{ unit }}&lt;/th&gt;&lt;th class="m pe-3"&gt;Доля&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;{% for r in stock %}&lt;tr {% if r.fact %}style="background:#FFF6D6"{% endif %}&gt;\n          &lt;td class="ps-3"&gt;{{ r.month }} {% if r.fact %}&lt;span class="tag"&gt;факт&lt;/span&gt;{% endif %}&lt;/td&gt;\n          &lt;td class="m"&gt;{{ r.total }}&lt;/td&gt;&lt;td class="m"&gt;{{ r.bad }}&lt;/td&gt;&lt;td class="m pe-3 fw-semibold"&gt;{{ r.share }}&lt;/td&gt;&lt;/tr&gt;{% endfor %}&lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    &lt;div class="p-2 px-3 small muted"&gt;Это запас, а не поток: какая доля портфеля будет в «{{ label }}» в конце месяца. Каждый месяц портфель\n      переходит между состояниями так, как переходил в последние 12 месяцев (с погашениями), а плановая выдача добавляется в лучшее состояние.\n      Если доля здесь растёт, а поток выше тоже растёт — сигнал одинаковый.&lt;/div&gt;\n  &lt;/div&gt;\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})

TUTORIALS.append({'title': 'VIN-11. templates/vintage/chart.html', 'category': 'programming', 'order': 11, 'summary': 'One line chart as plain SVG, used for the year curves and the passports comparison.', 'content': '<p>Step 11 of 11. Save as <code>vintage/templates/vintage/chart.html</code>.</p>\n<h3>templates/vintage/chart.html</h3>\n<pre><code class="language-html">{% comment %}\n  One line chart as plain SVG: {% include "vintage/chart.html" with c=curves %}.\n  c comes from process.chart(): lines (points, colour, dashed), grid, ticks, sizes.\n{% endcomment %}\n&lt;svg class="curves" viewBox="0 0 {{ c.W }} {{ c.H }}" role="img"&gt;\n  {% for g in c.grid %}&lt;line class="grid" x1="{{ c.L }}" x2="{{ c.x_end }}" y1="{{ g.y }}" y2="{{ g.y }}"/&gt;\n  &lt;text x="{{ c.L|add:\'-6\' }}" y="{{ g.y }}" text-anchor="end" dominant-baseline="middle"&gt;{{ g.label }}&lt;/text&gt;{% endfor %}\n  &lt;line class="axis" x1="{{ c.L }}" x2="{{ c.x_end }}" y1="{{ c.y_axis }}" y2="{{ c.y_axis }}"/&gt;\n  {% for t in c.ticks %}&lt;text x="{{ t.x }}" y="{{ c.H|add:\'-10\' }}" text-anchor="middle"&gt;{{ t.label }}&lt;/text&gt;{% endfor %}\n  {% for line in c.lines %}&lt;polyline class="{% if line.dashed %}typ{% endif %}" points="{{ line.points }}" stroke="{{ line.colour }}"&gt;&lt;title&gt;{{ line.name }}&lt;/title&gt;&lt;/polyline&gt;{% endfor %}\n&lt;/svg&gt;\n&lt;div class="legend mt-2"&gt;\n  {% for line in c.lines %}&lt;span&gt;{% if line.dashed %}&lt;i class="typ"&gt;&lt;/i&gt;{% else %}&lt;i style="background:{{ line.colour }}"&gt;&lt;/i&gt;{% endif %}{{ line.name }}&lt;/span&gt;{% endfor %}\n&lt;/div&gt;\n</code></pre>\n'})
